CREATE OR REPLACE FUNCTION public.account_group_member_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  group_org uuid;
  group_dimension text;
  account_org uuid;
  old_lock_key text;
  new_lock_key text;
  first_lock_key text;
  second_lock_key text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'account-group-pin:' || OLD.org_id::text || ':' || OLD.dimension || ':' || OLD.account_id::text,
        0
      )
    );
    RETURN OLD;
  END IF;

  SELECT group_row.org_id, group_row.dimension
    INTO group_org, group_dimension
    FROM public.account_groups group_row
   WHERE group_row.id = NEW.group_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account group % does not exist', NEW.group_id
      USING ERRCODE = '23503';
  END IF;
  IF group_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'account group % belongs to another organization', NEW.group_id
      USING ERRCODE = '23514';
  END IF;
  IF NEW.dimension IS DISTINCT FROM group_dimension THEN
    RAISE EXCEPTION 'account group member dimension must match its group'
      USING ERRCODE = '23514';
  END IF;

  SELECT account_row.org_id
    INTO account_org
    FROM public.accounts account_row
   WHERE account_row.id = NEW.account_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account % does not exist', NEW.account_id
      USING ERRCODE = '23503';
  END IF;
  IF account_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'account % belongs to another organization', NEW.account_id
      USING ERRCODE = '23514';
  END IF;

  new_lock_key := 'account-group-pin:' || NEW.org_id::text || ':' || NEW.dimension || ':' || NEW.account_id::text;
  IF TG_OP = 'UPDATE' THEN
    old_lock_key := 'account-group-pin:' || OLD.org_id::text || ':' || OLD.dimension || ':' || OLD.account_id::text;
    first_lock_key := LEAST(old_lock_key, new_lock_key);
    second_lock_key := GREATEST(old_lock_key, new_lock_key);
    PERFORM pg_advisory_xact_lock(hashtextextended(first_lock_key, 0));
    IF second_lock_key IS DISTINCT FROM first_lock_key THEN
      PERFORM pg_advisory_xact_lock(hashtextextended(second_lock_key, 0));
    END IF;
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended(new_lock_key, 0));
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.account_posting_classification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_has_lines boolean;
begin
  if new.type is not distinct from old.type
     and new.is_summary is not distinct from old.is_summary then
    return new;
  end if;

  select exists (
    select 1
      from journal_lines
     where org_id = old.org_id
       and account_id = old.id
  ) into v_has_lines;

  if not v_has_lines then
    return new;
  end if;

  if new.type is distinct from old.type then
    raise exception 'account % type cannot change after journal lines exist', old.id
      using errcode = '23514', constraint = 'accounts_type_has_transactions';
  end if;

  if new.is_summary is distinct from old.is_summary then
    raise exception 'account % summary classification cannot change after journal lines exist', old.id
      using errcode = '23514', constraint = 'accounts_summary_has_transactions';
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ai_decisions_refuse_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN COALESCE(OLD, NEW);
  END IF;
  RAISE EXCEPTION 'ai_decisions is append-only: decisions cannot be updated or deleted; record a new row (capability %, subject %)',
    COALESCE(OLD.capability_key, NEW.capability_key),
    COALESCE(OLD.subject_kind, NEW.subject_kind);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.allocation_rule_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_version uuid;
begin
  v_version := coalesce(new.version_id, old.version_id);
  select status into v_status from public.allocation_rule_versions where id = v_version;
  if v_status is not null and v_status <> 'draft' then
    raise exception 'allocation rule version % is %; its targets are immutable', v_version, v_status;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.allocation_rule_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if old.status = 'draft' then
    return new;
  end if;
  if old.status = 'retired' then
    raise exception 'allocation rule version % is retired and immutable', old.id;
  end if;
  -- published: allow draft→published transition already applied; now lock the definition
  if new.status not in ('published', 'retired') then
    raise exception 'allocation rule version % is published; it can only be retired', old.id;
  end if;
  if row(new.rule_id, new.version_no, new.effective_from, new.effective_to, new.book_scope, new.book_ids,
         new.document_kinds, new.account_scope, new.dimension_filters, new.apply_policy, new.source_measure,
         new.basis_kind, new.driver_id, new.driver_as_of, new.basis_config, new.target_kind, new.dynamic_target,
         new.impact, new.offset_account_id, new.residual_policy, new.residual_target_id, new.solve_method,
         new.memo_template, new.line_description_template, new.definition_hash, new.published_at, new.published_by)
     is distinct from
     row(old.rule_id, old.version_no, old.effective_from, old.effective_to, old.book_scope, old.book_ids,
         old.document_kinds, old.account_scope, old.dimension_filters, old.apply_policy, old.source_measure,
         old.basis_kind, old.driver_id, old.driver_as_of, old.basis_config, old.target_kind, old.dynamic_target,
         old.impact, old.offset_account_id, old.residual_policy, old.residual_target_id, old.solve_method,
         old.memo_template, old.line_description_template, old.definition_hash, old.published_at, old.published_by)
  then
    raise exception 'allocation rule version % is published; its definition is immutable (retire it and publish a new version)', old.id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.app_check_open()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_line numeric(19,4);
  v_applied numeric(19,4);
  v_transaction numeric(19,4);
begin
  if new.unapplied_at is not null then return new; end if;
  -- target side: total applied to the open item <= |line amount|
  select abs(amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(amount), 0) into v_applied
    from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.amount > v_line then
    raise exception 'application exceeds open amount on target line % (% applied of %)',
      new.to_line_id, v_applied + new.amount, v_line;
  end if;

  select abs(txn_amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(target_transaction_amount), 0) into v_transaction from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.target_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on target line %', new.to_line_id using errcode = '23514';
  end if;

  -- source side uses its independently recorded carrying amount.
  select abs(amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_amount), 0) into v_applied
    from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.source_amount > v_line then
    raise exception 'application exceeds available amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  select abs(txn_amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_transaction_amount), 0) into v_transaction from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.source_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_validate_endpoints()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_from journal_lines%rowtype;
  v_to journal_lines%rowtype;
  v_fx fx_rates%rowtype;
  v_status_count integer;
begin
  -- Bulk migration / sandbox-clone copies pre-validated application rows through
  -- ob_rebase before their journal lines exist in the target, so this row-by-row
  -- cross-reference check can't hold mid-copy. 'set local openbooks.migration = on'
  -- (transaction-scoped, direct-DB only) relaxes it; every normal write still
  -- validates in full.
  if coalesce(current_setting('openbooks.migration', true), 'off') = 'on' then
    return new;
  end if;
  -- Deterministic row locks serialize competing applications to either line.
  perform id from journal_lines
   where id in (new.from_line_id, new.to_line_id)
   order by id for update;
  select * into v_from from journal_lines where id = new.from_line_id;
  select * into v_to from journal_lines where id = new.to_line_id;
  if v_from.id is null or v_to.id is null or v_from.id = v_to.id then
    raise exception 'application endpoints must be two distinct journal lines' using errcode = '23514';
  end if;
  if v_from.org_id <> new.org_id or v_to.org_id <> new.org_id
     or v_from.org_id <> v_to.org_id then
    raise exception 'application endpoints must belong to the application tenant' using errcode = '23514';
  end if;
  if new.unapplied_at is not null then return new; end if;
  -- Parallel accounting books are representations, not additional balances.
  -- Posted entry book identity is immutable. The existing sorted endpoint
  -- locks below the migration exemption continue to serialize allocations.
  -- Keep this after the unapply return so legacy invalid evidence can be
  -- corrected through the ordinary audited unapplication lifecycle.
  if not exists (
    select 1 from journal_entries source_entry
    join journal_entries target_entry
      on target_entry.id = v_to.entry_id
     and target_entry.org_id = new.org_id
     and target_entry.book_id = source_entry.book_id
    where source_entry.id = v_from.entry_id
      and source_entry.org_id = new.org_id
  ) then
    raise exception 'application endpoints must share an accounting book' using errcode = '23514';
  end if;
  if not v_from.is_open_item or not v_to.is_open_item then
    raise exception 'applications require open-item journal lines' using errcode = '23514';
  end if;
  if v_from.account_id <> v_to.account_id
     or v_from.party_id is distinct from v_to.party_id
     or v_from.subsidiary_id <> v_to.subsidiary_id then
    raise exception 'application endpoints must share account, party, and subsidiary' using errcode = '23514';
  end if;
  if sign(v_from.amount) = sign(v_to.amount) then
    raise exception 'application endpoints must have opposite debit/credit signs' using errcode = '23514';
  end if;
  if v_from.currency <> new.source_transaction_currency
     or v_to.currency <> new.target_transaction_currency then
    raise exception 'application source and target currencies must match their journal lines' using errcode = '23514';
  end if;
  if abs(new.target_transaction_amount - round(new.source_transaction_amount * new.settlement_rate, 4)) > 0.0001 then
    raise exception 'application settlement rate does not cross-foot source and target transaction amounts' using errcode = '23514';
  end if;
  if new.source_transaction_currency = new.target_transaction_currency then
    if new.source_transaction_amount <> new.target_transaction_amount
       or new.settlement_rate <> 1
       or new.settlement_rate_source <> 'same_currency' then
      raise exception 'same-currency applications require equal transaction amounts and a rate of one' using errcode = '23514';
    end if;
  elsif new.settlement_rate_source = 'same_currency' then
    raise exception 'cross-currency applications require explicit settlement-rate evidence' using errcode = '23514';
  end if;
  if new.settlement_rate_source = 'provider' and new.settlement_fx_rate_id is null then
    raise exception 'provider settlement evidence requires an FX rate observation' using errcode = '23514';
  end if;
  if new.settlement_fx_rate_id is not null then
    select * into v_fx from fx_rates where id = new.settlement_fx_rate_id;
    if v_fx.id is null
       or v_fx.org_id <> new.org_id
       or v_fx.from_currency <> new.source_transaction_currency
       or v_fx.to_currency <> new.target_transaction_currency
       or v_fx.rate <> new.settlement_rate
       or v_fx.as_of > new.applied_on then
      raise exception 'settlement FX observation does not match the application evidence' using errcode = '23514';
    end if;
  end if;
  select count(*) into v_status_count from journal_entries
   where id in (v_from.entry_id, v_to.entry_id) and status = 'posted';
  if v_status_count <> 2 then
    raise exception 'applications may only connect posted journal entries' using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.assembly_disassembly_binding()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  operation_id uuid;
  operation public.assembly_disassemblies%ROWTYPE;
  source public.inventory_movements%ROWTYPE;
  component jsonb;
  actual_count integer;
BEGIN
  IF TG_TABLE_NAME='assembly_disassemblies' THEN operation_id:=NEW.id;
  ELSE operation_id:=NEW.assembly_disassembly_id; END IF;
  IF operation_id IS NULL THEN
    IF TG_TABLE_NAME='inventory_movements' THEN
    IF NEW.reverses_movement_id IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.inventory_movements m WHERE m.id=NEW.reverses_movement_id AND m.org_id=NEW.org_id AND m.assembly_disassembly_id IS NOT NULL) THEN
      RAISE EXCEPTION 'a disassembly reversal must retain its operation identity';
    END IF;
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO STRICT operation FROM public.assembly_disassemblies WHERE id=operation_id AND org_id=NEW.org_id;
  SELECT * INTO STRICT source FROM public.inventory_movements WHERE id=operation.build_movement_id AND org_id=operation.org_id;
  IF source.kind<>'assembly_build' OR source.status<>'posted' OR source.subsidiary_id<>operation.subsidiary_id
     OR operation.moved_on<source.moved_at::date OR NOT EXISTS(
       SELECT 1 FROM public.journal_entries e WHERE e.id=source.journal_entry_id AND e.org_id=operation.org_id
         AND e.book_id=operation.book_id AND e.origin='inventory' AND e.custom ? 'assemblyBuild') THEN
    RAISE EXCEPTION 'disassembly must bind to its original build, organization, legal entity and accounting book';
  END IF;
  IF operation.journal_entry_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.journal_entries e WHERE e.id=operation.journal_entry_id AND e.org_id=operation.org_id
      AND e.book_id=operation.book_id AND e.subsidiary_id=operation.subsidiary_id AND e.origin='inventory' AND e.status IN ('posted','reversed')
      AND e.custom->'assemblyDisassembly'->>'operationId'=operation.id::text
      AND e.custom->'assemblyDisassembly'->'components'=operation.components) THEN
      RAISE EXCEPTION 'disassembly journal must retain the same operation and recovery evidence';
    END IF;
  ELSIF operation.withdrawn_value<>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(operation.components) c WHERE (c->>'value')::numeric<>0) THEN
    RAISE EXCEPTION 'a value-carrying disassembly requires a posted journal';
  END IF;
  SELECT count(*) INTO actual_count FROM public.inventory_movements m WHERE m.org_id=operation.org_id
    AND m.assembly_disassembly_id=operation.id AND m.kind IN ('assembly_disassembly','assembly_recovery');
  IF actual_count<>1+jsonb_array_length(operation.components) OR NOT EXISTS(
    SELECT 1 FROM public.inventory_movements m WHERE m.org_id=operation.org_id AND m.assembly_disassembly_id=operation.id
      AND m.kind='assembly_disassembly' AND m.item_id=source.item_id AND m.subsidiary_id=source.subsidiary_id
      AND m.stock_location_id=source.stock_location_id AND m.quantity=-operation.quantity AND m.total_value=-operation.withdrawn_value
      AND m.journal_entry_id IS NOT DISTINCT FROM operation.journal_entry_id AND m.status='posted') THEN
    RAISE EXCEPTION 'disassembly must record one complete quantity and value operation';
  END IF;
  FOR component IN SELECT value FROM jsonb_array_elements(operation.components) LOOP
    IF NOT component ?& ARRAY['itemId','quantity','value','originalCost']
      OR component->>'itemId' IS NULL OR component->>'quantity' IS NULL OR component->>'value' IS NULL OR component->>'originalCost' IS NULL
      OR (component->>'quantity')::numeric<=0 OR (component->>'value')::numeric<0 OR (component->>'originalCost')::numeric<0
      OR NOT EXISTS(SELECT 1 FROM public.inventory_movements m WHERE m.org_id=operation.org_id AND m.assembly_disassembly_id=operation.id
        AND m.kind='assembly_recovery' AND m.item_id=(component->>'itemId')::uuid AND m.subsidiary_id=source.subsidiary_id
        AND m.stock_location_id=source.stock_location_id AND m.quantity=(component->>'quantity')::numeric AND m.total_value=(component->>'value')::numeric
        AND m.journal_entry_id IS NOT DISTINCT FROM operation.journal_entry_id AND m.status='posted') THEN
      RAISE EXCEPTION 'each recovered component must match its recorded quantity, cost and legal entity';
    END IF;
  END LOOP;
  IF TG_TABLE_NAME='inventory_movements' THEN
  IF NEW.kind='return' AND NOT EXISTS(
    SELECT 1 FROM public.inventory_movements m WHERE m.id=NEW.reverses_movement_id AND m.org_id=NEW.org_id
      AND m.assembly_disassembly_id=operation.id AND m.item_id=NEW.item_id AND m.subsidiary_id=NEW.subsidiary_id
      AND m.stock_location_id=NEW.stock_location_id AND NEW.quantity=-m.quantity AND NEW.total_value=-m.total_value) THEN
    RAISE EXCEPTION 'a disassembly reversal must mirror its original movement';
  END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.assembly_disassembly_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'physical disassembly evidence is immutable; use its controlled inventory movement reversal';
END $function$

CREATE OR REPLACE FUNCTION public.assert_document_totals_match_lines(p_document_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_kind text;
    v_stored_subtotal numeric;
    v_stored_tax numeric;
    v_stored_total numeric;
    v_line_count integer;
    v_amount_sum numeric;
    v_tax_sum numeric;
    v_debit_sum numeric;
    v_want_subtotal numeric;
    v_want_tax numeric;
    v_want_total numeric;
BEGIN
    SELECT kind, subtotal, tax_total, total
      INTO v_kind, v_stored_subtotal, v_stored_tax, v_stored_total
      FROM public.documents
     WHERE id = p_document_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*)::int,
           coalesce(sum(l.amount), 0),
           coalesce(sum(l.tax_amount), 0),
           coalesce(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
      INTO v_line_count, v_amount_sum, v_tax_sum, v_debit_sum
      FROM public.document_lines l
     WHERE l.document_id = p_document_id AND l.org_id = p_org_id;
    IF v_line_count = 0 THEN
        RETURN;
    END IF;
    IF v_kind IN ('journal', 'pay_run') THEN
        v_want_tax := v_tax_sum;
        v_want_total := v_debit_sum;
        v_want_subtotal := v_debit_sum - v_tax_sum;
    ELSE
        v_want_subtotal := v_amount_sum;
        v_want_tax := v_tax_sum;
        v_want_total := v_amount_sum + v_tax_sum;
    END IF;
    IF v_stored_subtotal IS DISTINCT FROM v_want_subtotal
       OR v_stored_tax IS DISTINCT FROM v_want_tax
       OR v_stored_total IS DISTINCT FROM v_want_total THEN
        RAISE EXCEPTION
            'document % header totals do not tie to its lines: stored subtotal %, tax_total %, total % but its % line(s) sum to subtotal %, tax_total %, total %',
            p_document_id, v_stored_subtotal, v_stored_tax, v_stored_total,
            v_line_count, v_want_subtotal, v_want_tax, v_want_total
            USING ERRCODE = 'check_violation';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.asset_basis_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'asset basis changes are immutable; approve an adjusting change'; END IF;
 IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=NEW.change_id AND f.org_id=NEW.org_id AND f.domain='asset' AND f.subject_id=NEW.asset_id AND f.status='approved') THEN RAISE EXCEPTION 'asset basis requires independent approval for this asset'; END IF;
 IF NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.id=NEW.asset_id AND a.org_id=NEW.org_id) OR NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.id=NEW.book_id AND b.org_id=NEW.org_id) THEN RAISE EXCEPTION 'asset basis references another organization'; END IF;
 IF NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.id=NEW.journal_entry_id AND e.org_id=NEW.org_id AND e.book_id=NEW.book_id AND e.status='posted' AND e.posting_date=NEW.effective_on AND e.subsidiary_id=(SELECT a.subsidiary_id FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.asset_id)) THEN RAISE EXCEPTION 'asset basis requires its posted book journal'; END IF;
 IF NEW.stub_journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.id=NEW.stub_journal_entry_id AND e.org_id=NEW.org_id AND e.book_id=NEW.book_id AND e.status='posted' AND e.posting_date=NEW.effective_on AND e.subsidiary_id=(SELECT a.subsidiary_id FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.asset_id)) THEN RAISE EXCEPTION 'elapsed depreciation must reference its posted book journal'; END IF;
 -- Absence must match too: accepting NULL when the approval contains a group
 -- component would silently make consolidation infer a legal-book fraction.
 IF NEW.group_component IS DISTINCT FROM (SELECT f.before_state->'groupComponents'->NEW.book_id::text FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.operation IN('partial_disposal','intercompany_transfer')) OR (NEW.group_component IS NOT NULL AND NOT EXISTS(SELECT 1 FROM asset_transfer_bases t WHERE t.org_id=NEW.org_id AND t.receiving_asset_id=NEW.asset_id AND t.book_id=NEW.book_id AND t.reversed_by_change_id IS NULL)) THEN RAISE EXCEPTION 'group component basis must match its independently approved retained and removed measurements'; END IF;
 IF NEW.effective_on<>(SELECT f.effective_on FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id) THEN RAISE EXCEPTION 'basis date differs from the approved effective date'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.asset_changed_basis_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM asset_basis_changes x WHERE x.org_id=OLD.org_id AND x.asset_id=OLD.id) OR OLD.transferred_from_asset_id IS NOT NULL THEN
  IF (NEW.org_id,NEW.id,NEW.subsidiary_id,NEW.category_id,NEW.acquisition_cost,NEW.salvage_value,NEW.in_service_on,NEW.opening_accumulated_depreciation,NEW.opening_accumulated_as_of,NEW.asset_account_id,NEW.accumulated_depreciation_account_id,NEW.depreciation_expense_account_id,NEW.depreciation_method,NEW.depreciation_method_id,NEW.useful_life_months,NEW.depreciation_rate_percent,NEW.depreciation_convention,NEW.depreciation_units_total,NEW.transferred_from_asset_id) IS DISTINCT FROM (OLD.org_id,OLD.id,OLD.subsidiary_id,OLD.category_id,OLD.acquisition_cost,OLD.salvage_value,OLD.in_service_on,OLD.opening_accumulated_depreciation,OLD.opening_accumulated_as_of,OLD.asset_account_id,OLD.accumulated_depreciation_account_id,OLD.depreciation_expense_account_id,OLD.depreciation_method,OLD.depreciation_method_id,OLD.useful_life_months,OLD.depreciation_rate_percent,OLD.depreciation_convention,OLD.depreciation_units_total,OLD.transferred_from_asset_id) THEN RAISE EXCEPTION 'approved asset basis cannot be rewritten; propose a lifecycle change'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.asset_event_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source record;
BEGIN
 IF TG_OP IN('UPDATE','DELETE') THEN
  IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN coalesce(NEW,OLD); END IF;
  RAISE EXCEPTION 'asset lifecycle evidence is append-only; post a linked reversal event';
 END IF;
 IF NEW.kind='reversed' THEN
  SELECT * INTO source FROM asset_events WHERE id=NEW.reverses_event_id FOR SHARE;
  IF source.id IS NULL OR source.org_id<>NEW.org_id OR source.asset_id<>NEW.asset_id OR source.kind NOT IN('revalued','impaired','disposed','written_off','partially_disposed','transferred','acquired') THEN RAISE EXCEPTION 'an asset reversal must reference a reversible event for the same tenant and asset'; END IF;
  IF source.financial_change_id IS NOT NULL THEN
   IF NEW.book_id IS DISTINCT FROM source.book_id OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.financial_change_id AND f.domain='asset' AND f.operation='reversal' AND f.status='approved' AND f.payload->>'sourceChangeId'=source.financial_change_id::text) THEN RAISE EXCEPTION 'governed asset events require the approved correction of their original change and book'; END IF;
  ELSIF source.kind IN('acquired','partially_disposed','transferred') THEN
   RAISE EXCEPTION 'this acquisition or transfer has no governed correction evidence';
  END IF;
  IF source.financial_change_id IS NOT NULL AND ((source.journal_entry_id IS NULL) IS DISTINCT FROM (NEW.journal_entry_id IS NULL) OR (source.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.reverses_entry_id=source.journal_entry_id AND e.status='posted'))) THEN RAISE EXCEPTION 'asset correction event must link the exact reversing journal'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.asset_lifecycle_reference_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='fixed_assets' THEN
  IF NEW.transferred_from_asset_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.transferred_from_asset_id AND a.id<>NEW.id) THEN RAISE EXCEPTION 'the source asset must belong to the same organization'; END IF;
 ELSE
  IF NEW.financial_change_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM financial_changes f JOIN fixed_assets a ON a.org_id=f.org_id AND a.id=NEW.asset_id WHERE f.org_id=NEW.org_id AND f.id=NEW.financial_change_id AND f.domain='asset' AND f.status='approved' AND f.effective_on=NEW.occurred_on AND (f.subject_id=a.id OR (a.transferred_from_asset_id=f.subject_id AND (NEW.kind='acquired' AND f.operation='intercompany_transfer' OR NEW.kind='reversed' AND f.operation='reversal')))) THEN RAISE EXCEPTION 'asset event requires independent approval for this asset and effective date'; END IF;
  IF NEW.book_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.org_id=NEW.org_id AND b.id=NEW.book_id) OR (NEW.journal_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=NEW.journal_entry_id AND e.book_id=NEW.book_id))) THEN RAISE EXCEPTION 'asset event book must match its tenant and journal'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.asset_transfer_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_TABLE_NAME='asset_transfer_bases' THEN
  IF TG_OP='INSERT' THEN
   IF NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.source_asset_id AND a.subsidiary_id=NEW.seller_subsidiary_id) OR NOT EXISTS(SELECT 1 FROM fixed_assets a WHERE a.org_id=NEW.org_id AND a.id=NEW.receiving_asset_id AND a.subsidiary_id=NEW.buyer_subsidiary_id AND a.transferred_from_asset_id=NEW.source_asset_id) OR NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=NEW.org_id AND s.id=NEW.elimination_subsidiary_id AND s.is_elimination AND s.base_currency=NEW.group_currency) OR NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.org_id=NEW.org_id AND b.id=NEW.book_id) THEN RAISE EXCEPTION 'transfer evidence must reference its tenant, asset owners, book and group currency'; END IF;
   IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.subject_id=NEW.source_asset_id AND f.domain='asset' AND f.operation='intercompany_transfer' AND f.status='approved') THEN RAISE EXCEPTION 'transfer basis requires its independently approved change'; END IF;
  ELSIF TG_OP='UPDATE' THEN
   IF OLD.reversed_by_change_id IS NOT NULL OR NEW.reversed_by_change_id IS NULL OR NEW.reversed_on IS NULL OR NEW.reversed_on<OLD.effective_on OR (to_jsonb(NEW)-ARRAY['reversed_by_change_id','reversed_on']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['reversed_by_change_id','reversed_on']) OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id AND f.domain='asset' AND f.operation='reversal' AND f.subject_id=OLD.source_asset_id AND f.payload->>'sourceChangeId'=OLD.change_id::text AND f.status='approved') THEN RAISE EXCEPTION 'only an independently approved reversal may close a transfer basis'; END IF;
  ELSE RAISE EXCEPTION 'asset transfer evidence is immutable'; END IF;
 ELSE
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'asset transfer consolidation evidence is immutable'; END IF;
  IF NOT EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN journal_entries e ON e.org_id=b.org_id AND e.id=NEW.journal_entry_id AND e.book_id=b.book_id AND e.subsidiary_id=b.elimination_subsidiary_id AND e.status='posted' AND e.period_id=NEW.period_id JOIN accounting_periods p ON p.org_id=e.org_id AND p.id=e.period_id WHERE b.org_id=NEW.org_id AND b.id=NEW.transfer_id) THEN RAISE EXCEPTION 'asset consolidation evidence requires its posted group/book journal'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.asset_transfer_measurement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'approved group asset measurements are immutable; propose a correcting group valuation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM asset_transfer_bases b JOIN asset_events v ON v.org_id=b.org_id AND v.asset_id=b.receiving_asset_id JOIN journal_entries e ON e.org_id=v.org_id AND e.id=v.journal_entry_id JOIN financial_changes f ON f.org_id=b.org_id AND f.id=NEW.change_id WHERE b.org_id=NEW.org_id AND b.id=NEW.transfer_id AND b.reversed_by_change_id IS NULL AND v.id=NEW.source_event_id AND v.kind IN('impaired','revalued') AND v.occurred_on=NEW.effective_on AND e.book_id=b.book_id AND e.status='posted' AND f.subject_id=b.receiving_asset_id AND f.domain='asset' AND f.operation='group_valuation' AND f.status='approved' AND f.effective_on=NEW.effective_on) THEN RAISE EXCEPTION 'group valuation requires its approved asset, book and source valuation'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.audit_log_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'audit_log is append-only';
end $function$

CREATE OR REPLACE FUNCTION public.benefit_enrollment_workflow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE run_row public.flow_runs%ROWTYPE; mode text;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.status NOT IN ('elected','waived') OR NEW.flow_run_id IS NOT NULL OR NEW.submission_snapshot IS NOT NULL OR NEW.decision_snapshot IS NOT NULL THEN
   RAISE EXCEPTION 'Create a benefit election, then submit it through the plan approval setting; active coverage cannot be supplied on creation.' USING ERRCODE='23514';
  END IF;
  IF NEW.replaces_enrollment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.hrm_benefit_enrollments e WHERE e.org_id=NEW.org_id AND e.id=NEW.replaces_enrollment_id AND e.employment_id=NEW.employment_id AND e.plan_id=NEW.plan_id AND e.status='active' AND e.effective_from<NEW.effective_from) THEN RAISE EXCEPTION 'A successor must replace active coverage on the same employment and plan from a later date.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
  OLD.status='elected' AND NEW.status IN ('pending_approval','active','cancelled') OR
  OLD.status='pending_approval' AND NEW.status IN ('active','cancelled') OR
  OLD.status='active' AND (NEW.status='ended' OR (NEW.status='cancelled'
    AND NOT EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.enrollment_id=OLD.id AND a.status IN ('committed','voided'))
    AND EXISTS(SELECT 1 FROM public.worker_employment_versions v WHERE v.org_id=OLD.org_id AND v.employment_id=OLD.employment_id AND v.recorded_until IS NULL AND v.status='terminated' AND v.effective_from<=OLD.effective_from))) OR OLD.status='waived' AND NEW.status='cancelled') THEN
  RAISE EXCEPTION 'This benefit lifecycle transition is not permitted; use the enrollment record actions or create a successor election.' USING ERRCODE='23514';
 END IF;
 IF (OLD.submission_snapshot IS NOT NULL OR OLD.status IN ('active','ended')) AND
  ROW(NEW.org_id,NEW.employment_id,NEW.plan_id,NEW.currency,NEW.effective_from) IS DISTINCT FROM
  ROW(OLD.org_id,OLD.employment_id,OLD.plan_id,OLD.currency,OLD.effective_from) THEN
  RAISE EXCEPTION 'Submitted coverage identity and start date are immutable; create a successor enrollment.' USING ERRCODE='23514';
 END IF;
 IF OLD.status='ended' AND NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
  RAISE EXCEPTION 'Ended coverage dates are immutable; use a correcting successor election.' USING ERRCODE='23514';
 END IF;
 IF OLD.submission_snapshot IS NULL AND NEW.submission_snapshot IS NOT NULL THEN
  IF OLD.status<>'elected' OR NEW.submission_snapshot IS DISTINCT FROM public.benefit_enrollment_submission_source(OLD.org_id,OLD.id)
   OR NEW.submitted_by IS NULL OR NEW.submitted_by IS DISTINCT FROM NEW.updated_by OR NEW.submitted_at IS NULL THEN
   RAISE EXCEPTION 'Benefit submission must pin the current plan approval setting and exact contribution elections; submit through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.submission_snapshot IS NOT NULL AND (NEW.submission_snapshot IS DISTINCT FROM OLD.submission_snapshot OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
  OR NEW.class_key IS DISTINCT FROM OLD.class_key OR NEW.match_eligible IS DISTINCT FROM OLD.match_eligible OR NEW.replaces_enrollment_id IS DISTINCT FROM OLD.replaces_enrollment_id) THEN
  RAISE EXCEPTION 'Submitted benefit evidence is immutable; change the enrollment through its record action.' USING ERRCODE='23514';
 END IF;
 IF OLD.status IN ('active','ended') AND (NEW.class_key IS DISTINCT FROM OLD.class_key OR NEW.match_eligible IS DISTINCT FROM OLD.match_eligible) THEN
  RAISE EXCEPTION 'Active contribution classification is immutable; change the enrollment through its record action.' USING ERRCODE='23514';
 END IF;
 IF OLD.decision_snapshot IS NOT NULL AND NEW.decision_snapshot IS DISTINCT FROM OLD.decision_snapshot THEN RAISE EXCEPTION 'Benefit approval decisions are immutable; create a successor enrollment.' USING ERRCODE='23514'; END IF;
 IF OLD.flow_run_id IS NOT NULL AND NEW.flow_run_id IS DISTINCT FROM OLD.flow_run_id THEN RAISE EXCEPTION 'Benefit workflow linkage is immutable; create a successor enrollment.' USING ERRCODE='23514'; END IF;
 IF NEW.status='active' AND OLD.status<>'active' THEN
  IF NEW.submission_snapshot IS NULL OR NEW.decision_snapshot IS NULL OR NEW.decision_snapshot->>'outcome' IS DISTINCT FROM 'approved'
   OR NEW.submitted_by IS NULL OR NEW.submitted_at IS NULL OR NOT EXISTS (SELECT 1 FROM public.hrm_benefit_enrollment_terms t WHERE t.org_id=NEW.org_id AND t.enrollment_id=NEW.id) THEN
   RAISE EXCEPTION 'Coverage requires explicit contribution elections and submission evidence; submit the enrollment through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.flow_run_id IS NOT NULL THEN
  SELECT * INTO run_row FROM public.flow_runs WHERE org_id=NEW.org_id AND id=NEW.flow_run_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id AND trigger='on_submit';
  IF NOT FOUND OR run_row.created_by IS DISTINCT FROM NEW.submitted_by OR NEW.submission_snapshot->>'approvalMode' IS DISTINCT FROM 'flows'
   OR run_row.context->>'planId' IS DISTINCT FROM NEW.plan_id::text OR run_row.context->>'employmentId' IS DISTINCT FROM NEW.employment_id::text
   OR run_row.context->'contributions' IS DISTINCT FROM NEW.submission_snapshot->'contributions' THEN
   RAISE EXCEPTION 'Benefit workflow evidence must match the enrollment, organization, submitter and elections; submit through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status='pending_approval' AND OLD.status<>'pending_approval' AND NEW.flow_run_id IS NULL THEN RAISE EXCEPTION 'Submit the enrollment to a configured native Flow before pending approval.' USING ERRCODE='23514'; END IF;
 IF NEW.status='active' AND OLD.status<>'active' THEN
  mode:=NEW.decision_snapshot->>'mode';
  IF mode='not_required' THEN
   IF NEW.flow_run_id IS NOT NULL OR NEW.submission_snapshot->>'approvalMode' IS DISTINCT FROM 'none'
    OR NEW.decision_snapshot->>'approvalMode' IS DISTINCT FROM 'none' OR NEW.decision_snapshot->>'planId' IS DISTINCT FROM NEW.plan_id::text THEN
    RAISE EXCEPTION 'No-approval coverage requires the pinned plan setting; submit through its record action.' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.flow_run_id IS NULL OR NEW.decision_snapshot->>'runId' IS DISTINCT FROM NEW.flow_run_id::text
    OR EXISTS (SELECT 1 FROM public.flow_gates WHERE org_id=NEW.org_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id AND status IN ('pending','escalated','rejected'))
    OR EXISTS (SELECT 1 FROM public.flow_runs WHERE org_id=NEW.org_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id AND (status='failed' OR
      status IN ('running','waiting') AND (mode<>'human' OR current_setting('openbooks.hrm_benefit_release',true) IS DISTINCT FROM NEW.org_id::text || ':' || NEW.id::text || ':' || NEW.updated_by::text))) THEN
    RAISE EXCEPTION 'Benefit approval stages remain incomplete; complete the assigned decisions in Approvals.' USING ERRCODE='23514';
   END IF;
   IF mode='automatic' THEN
    IF run_row.status<>'completed' OR run_row.context->'submissionPolicy'->>'ungatedOutcome' IS DISTINCT FROM 'apply'
     OR EXISTS (SELECT 1 FROM public.flow_gates WHERE org_id=NEW.org_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id) THEN RAISE EXCEPTION 'Direct coverage needs explicit completed ungated Flow evidence.' USING ERRCODE='23514'; END IF;
   ELSIF mode='human' THEN
    IF current_setting('openbooks.hrm_benefit_release',true) IS DISTINCT FROM NEW.org_id::text || ':' || NEW.id::text || ':' || NEW.updated_by::text THEN
     RAISE EXCEPTION 'Human benefit approval must release through its assigned native Flow decision; use Approvals.' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.flow_gates WHERE org_id=NEW.org_id AND subject_kind='hrm_benefit_enrollment' AND subject_id=NEW.id AND status='approved' AND decided_by=NEW.updated_by AND decided_at IS NOT NULL) THEN RAISE EXCEPTION 'No native approval decision authorizes this enrollment; decide its assigned gate in Approvals.' USING ERRCODE='23514'; END IF;
   ELSE RAISE EXCEPTION 'Benefit decisions require explicit no-approval, direct Flow processing or native human approval.' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recovery_rule_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s WHERE s.org_id=NEW.org_id AND s.rule_id=NEW.id)
  AND (NEW.kind<>'employee_deduction' OR NEW.unpaid_period_treatment<>'carry' OR NEW.arrears_plan_id IS NULL) THEN
  RAISE EXCEPTION 'This rule owns insured premium recovery; preserve its native carry deduction or replace the effective-dated rule.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s WHERE s.org_id=NEW.org_id AND s.premium_rule_id=NEW.id)
  AND (NEW.kind NOT IN ('employer_contribution','taxable_non_cash') OR NEW.basis NOT IN ('per_period','per_month','per_year')) THEN
  RAISE EXCEPTION 'This insured premium is linked to recovery; preserve its flat employer premium treatment or replace the effective-dated rule.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources a JOIN public.hrm_benefit_recovery_sources b
  ON b.org_id=a.org_id AND b.premium_rule_id=a.premium_rule_id AND b.rule_id<>a.rule_id
  JOIN public.hrm_benefit_contribution_rules prior_rule ON prior_rule.org_id=b.org_id AND prior_rule.id=b.rule_id
  WHERE a.org_id=NEW.org_id AND a.rule_id=NEW.id AND
   daterange(prior_rule.effective_from,COALESCE(prior_rule.effective_to,DATE '9999-12-31'),'[]') && daterange(NEW.effective_from,COALESCE(NEW.effective_to,DATE '9999-12-31'),'[]')) THEN
  RAISE EXCEPTION 'Insured premium recovery ownership dates overlap; close the prior rule before the successor begins.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recovery_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.rule_id=OLD.rule_id AND a.status IN ('committed','voided')) THEN RAISE EXCEPTION 'Recovery source configuration has committed payroll evidence; add an effective-dated replacement recovery rule.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF EXISTS(SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=NEW.org_id AND a.rule_id=NEW.rule_id AND a.status IN ('committed','voided')) THEN RAISE EXCEPTION 'Recovery source configuration has committed payroll evidence; add an effective-dated replacement recovery rule.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.hrm_benefit_contribution_rules r WHERE r.org_id=NEW.org_id AND r.plan_id=NEW.plan_id AND r.id=NEW.rule_id AND r.kind='employee_deduction' AND r.unpaid_period_treatment='carry' AND r.arrears_plan_id IS NOT NULL)
  OR NOT EXISTS(SELECT 1 FROM public.hrm_benefit_contribution_rules r WHERE r.org_id=NEW.org_id AND r.plan_id=NEW.plan_id AND r.id=NEW.premium_rule_id AND r.kind IN ('employer_contribution','taxable_non_cash') AND r.basis IN ('per_period','per_month','per_year')) THEN
  RAISE EXCEPTION 'Link a native employee recovery deduction to flat-period employer premium rules on the same plan.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.hrm_benefit_recovery_sources s
  JOIN public.hrm_benefit_contribution_rules prior_rule ON prior_rule.org_id=s.org_id AND prior_rule.id=s.rule_id
  JOIN public.hrm_benefit_contribution_rules new_rule ON new_rule.org_id=NEW.org_id AND new_rule.id=NEW.rule_id
  WHERE s.org_id=NEW.org_id AND s.premium_rule_id=NEW.premium_rule_id AND s.id<>NEW.id AND
   daterange(prior_rule.effective_from,COALESCE(prior_rule.effective_to,DATE '9999-12-31'),'[]') && daterange(new_rule.effective_from,COALESCE(new_rule.effective_to,DATE '9999-12-31'),'[]')) THEN
  RAISE EXCEPTION 'An insured premium already has a recovery owner during these dates; close the prior recovery rule before linking its successor.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recurring_audit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE row_value jsonb;
BEGIN
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
 VALUES ((row_value->>'org_id')::uuid,TG_TABLE_NAME,(row_value->>'id')::uuid,lower(TG_OP),
 jsonb_build_object('before',CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,'after',CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END),
 coalesce((row_value->>'updated_by')::uuid,(row_value->>'created_by')::uuid));
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recurring_configuration_lock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE tenant uuid;
BEGIN
 IF TG_OP = 'DELETE' THEN tenant := OLD.org_id; ELSE tenant := NEW.org_id; END IF;
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(tenant) THEN RETURN OLD; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:benefit-recurring:' || tenant::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recurring_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE run_status text; historical_through date;
BEGIN
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_TABLE_NAME='hrm_benefit_enrollment_terms' THEN
  IF EXISTS (SELECT 1 FROM public.hrm_benefit_enrollments e
  WHERE e.org_id=OLD.org_id AND e.id=OLD.enrollment_id AND (e.status<>'elected' OR e.submission_snapshot IS NOT NULL)) THEN
   RAISE EXCEPTION 'Submitted contribution elections are immutable; change the enrollment through its record action.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME <> 'pay_run_benefit_allocations' AND TG_OP = 'UPDATE' THEN
  SELECT max(a.period_to) INTO historical_through FROM public.pay_run_benefit_allocations a
  WHERE a.org_id=OLD.org_id AND a.status IN ('committed','voided') AND
   CASE TG_TABLE_NAME WHEN 'hrm_benefit_enrollment_terms' THEN a.term_id=OLD.id
    WHEN 'hrm_benefit_contribution_tiers' THEN a.source_snapshot #>> '{basis,tier,id}'=OLD.id::text
    ELSE a.rule_id=OLD.id END;
  IF NEW.effective_to IS NOT NULL AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to)
   AND (historical_through IS NULL OR NEW.effective_to>=historical_through)
   AND (to_jsonb(NEW)-'effective_to'-'updated_at'-'updated_by')=(to_jsonb(OLD)-'effective_to'-'updated_at'-'updated_by') THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME = 'pay_run_benefit_allocations' THEN
  SELECT r.run_status INTO run_status FROM public.pay_runs r WHERE r.org_id = OLD.org_id AND r.document_id = OLD.pay_run_document_id;
  IF OLD.status IN ('committed','voided') OR run_status IN ('committed','voided') THEN
   IF TG_OP = 'UPDATE' AND NEW.status = 'voided' AND OLD.status = 'committed' AND
      (to_jsonb(NEW) - 'status' - 'updated_at' - 'updated_by') = (to_jsonb(OLD) - 'status' - 'updated_at' - 'updated_by') THEN RETURN NEW; END IF;
   RAISE EXCEPTION 'Committed benefit allocations are immutable; use a reversing or correcting payroll run.' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'hrm_benefit_contribution_tiers' THEN
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id=OLD.org_id AND a.status IN ('committed','voided')
   AND a.source_snapshot #>> '{basis,tier,id}' = OLD.id::text) THEN
   RAISE EXCEPTION 'This contribution tier has committed payroll evidence; add an effective-dated replacement tier for future coverage.' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a WHERE a.org_id = OLD.org_id AND a.status IN ('committed','voided')
    AND CASE TG_TABLE_NAME WHEN 'hrm_benefit_enrollment_terms' THEN a.term_id = OLD.id ELSE a.rule_id = OLD.id END) THEN
   RAISE EXCEPTION 'This contribution configuration has committed payroll evidence; preserve it and add effective-dated replacement terms or a new rule.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recurring_run_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.run_status IN ('committed','voided') AND NEW.benefit_source_snapshot IS DISTINCT FROM OLD.benefit_source_snapshot THEN
  RAISE EXCEPTION 'Committed recurring benefit source evidence is immutable; use a correcting payroll run.';
 END IF;
 IF NEW.run_status = 'committed' AND OLD.run_status <> 'committed' THEN
  IF NEW.benefit_source_snapshot IS NULL THEN RAISE EXCEPTION 'Recurring benefit source evidence is missing; recalculate the pay run before committing.'; END IF;
  IF EXISTS (SELECT 1 FROM public.pay_run_benefit_allocations a LEFT JOIN public.pay_stub_lines l ON l.org_id=a.org_id AND l.id=a.pay_stub_line_id
    LEFT JOIN public.pay_stubs s ON s.org_id=l.org_id AND s.id=l.stub_id
    WHERE a.org_id=NEW.org_id AND a.pay_run_document_id=NEW.document_id AND a.amount>0
    AND (l.id IS NULL OR l.amount IS DISTINCT FROM a.amount OR s.pay_run_document_id IS DISTINCT FROM a.pay_run_document_id
    OR s.employment_id IS DISTINCT FROM a.employment_id OR l.component_id::text IS DISTINCT FROM (a.source_snapshot #>> '{rule,payComponentId}'))) THEN
   RAISE EXCEPTION 'A benefit allocation is missing its exact native payroll line; recalculate the pay run before committing.';
  END IF;
  UPDATE public.pay_run_benefit_allocations SET status = 'committed',updated_at = now(),updated_by = NEW.updated_by
   WHERE org_id = NEW.org_id AND pay_run_document_id = NEW.document_id AND status = 'calculated';
 ELSIF NEW.run_status = 'voided' AND OLD.run_status = 'committed' THEN
  UPDATE public.pay_run_benefit_allocations SET status = 'voided',updated_at = now(),updated_by = NEW.updated_by
   WHERE org_id = NEW.org_id AND pay_run_document_id = NEW.document_id AND status = 'committed';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.benefit_recurring_subject_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e record; r record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:benefit-recurring:' || NEW.org_id::text,0));
 SELECT * INTO e FROM public.hrm_benefit_enrollments WHERE org_id = NEW.org_id AND id = NEW.enrollment_id;
 SELECT * INTO r FROM public.hrm_benefit_contribution_rules WHERE org_id = NEW.org_id AND id = NEW.rule_id;
 IF e.status <> 'elected' OR e.submission_snapshot IS NOT NULL THEN RAISE EXCEPTION 'Submitted contribution elections are immutable; change the enrollment through its record action.'; END IF;
 IF e.plan_id IS DISTINCT FROM r.plan_id THEN
  RAISE EXCEPTION 'Contribution terms must belong to a rule on the enrollment plan; select a rule from that plan.';
 END IF;
 IF NEW.effective_from < e.effective_from OR (e.effective_to IS NOT NULL AND (NEW.effective_to IS NULL OR NEW.effective_to > e.effective_to)) THEN
  RAISE EXCEPTION 'Contribution terms must fit inside enrollment coverage; choose dates within that enrollment.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.billing_request_field_ticket_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  selection_count bigint;
BEGIN
  SELECT count(*)
    INTO selection_count
    FROM billing_request_field_tickets selected
   WHERE selected.org_id = new.org_id
     AND selected.billing_request_id = new.id;

  IF new.basis = 'field_ticket' AND selection_count = 0 THEN
    RAISE EXCEPTION
      'a Field Ticket billing request requires at least one relational ticket selection';
  END IF;

  IF new.basis <> 'field_ticket' AND selection_count <> 0 THEN
    RAISE EXCEPTION
      'Field Ticket selections may only belong to a field-ticket billing request';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM billing_request_field_tickets selected
      JOIN documents ticket
        ON ticket.id = selected.field_ticket_id
       AND ticket.org_id = selected.org_id
     WHERE selected.org_id = new.org_id
       AND selected.billing_request_id = new.id
       AND (
         ticket.kind <> 'field_ticket'
         OR ticket.project_id IS DISTINCT FROM new.project_id
       )
  ) THEN
    RAISE EXCEPTION
      'Field Ticket billing selections must remain in the request organization and project';
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.change_order_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.target_sov_line_id is not null and not exists (
    select 1
      from sov_lines sl
     where sl.id = new.target_sov_line_id
       and sl.org_id = new.org_id
       and sl.project_id = new.project_id
  ) then
    raise exception 'change-order target must belong to the same organization and project';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.change_set_items_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_id uuid := COALESCE(NEW.change_set_id, OLD.change_set_id);
  parent_org uuid;
  parent_status text;
BEGIN
  SELECT org_id, status
    INTO parent_org, parent_status
    FROM public.change_sets
   WHERE id = parent_id
   FOR UPDATE;
  -- ON DELETE CASCADE removes child rows as part of deleting their parent;
  -- allow that internal delete while rejecting orphaned standalone writes.
  IF parent_status IS NULL AND TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF parent_status IS NULL THEN
    RAISE EXCEPTION 'change set % does not exist', parent_id;
  END IF;
  IF parent_status <> 'draft' THEN
    RAISE EXCEPTION 'change set items are immutable after review (status=%)', parent_status;
  END IF;
  IF TG_OP <> 'DELETE' AND NEW.org_id <> parent_org THEN
    RAISE EXCEPTION 'change set item organization must match its change set';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.close_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception '% is append-only', tg_table_name;
end $function$

CREATE OR REPLACE FUNCTION public.compliance_record_renewal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  successor public.compliance_records%ROWTYPE;
BEGIN
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a superseded compliance record cannot be reinstated'
      USING ERRCODE = '23514';
  END IF;

  -- A renewal is the only legal operation that fills superseded_by_id.  The
  -- UPDATE row lock serializes competing transactions on the predecessor; the
  -- second waiter then sees the committed superseded state and is rejected.
  IF NEW.superseded_by_id IS NOT DISTINCT FROM OLD.superseded_by_id THEN
    IF NEW.status = 'superseded' AND NEW.superseded_by_id IS NULL THEN
      RAISE EXCEPTION
        'a superseded compliance record must identify its pending successor'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.superseded_by_id IS NULL THEN
    RAISE EXCEPTION
      'a compliance record supersession pointer cannot be cleared'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'superseded' OR OLD.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance record % has already been superseded; renew the current record instead',
      OLD.id
      USING ERRCODE = '23505';
  END IF;

  IF NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a compliance renewal must mark its predecessor superseded'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.superseded_by_id = NEW.id THEN
    RAISE EXCEPTION
      'a compliance record cannot supersede itself'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
    INTO successor
    FROM public.compliance_records
   WHERE id = NEW.superseded_by_id
   FOR KEY SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'compliance renewal successor % does not exist',
      NEW.superseded_by_id
      USING ERRCODE = '23503';
  END IF;

  IF successor.org_id IS DISTINCT FROM NEW.org_id
     OR successor.party_id IS DISTINCT FROM NEW.party_id
     OR successor.requirement_id IS DISTINCT FROM NEW.requirement_id
     OR successor.project_id IS DISTINCT FROM NEW.project_id
     OR successor.status <> 'pending_review'
     OR successor.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance renewal successor % must be a pending record for the same organization, vendor, requirement, and project',
      NEW.superseded_by_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.control_loss_hierarchy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF (NEW.parent_id,NEW.base_currency,NEW.is_active,NEW.is_elimination) IS DISTINCT FROM (OLD.parent_id,OLD.base_currency,OLD.is_active,OLD.is_elimination) AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=OLD.org_id AND loss.reversed_by_change_id IS NULL AND (loss.excluded_subsidiary_ids ? OLD.id::text OR OLD.id IN(loss.parent_subsidiary_id,loss.elimination_subsidiary_id))) THEN RAISE EXCEPTION 'the entity hierarchy and currency support an approved disposal; correct the disposal before changing its historical reporting scope'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.control_loss_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.reversed_by_change_id IS NULL AND NEW.reversed_by_change_id IS NOT NULL AND (to_jsonb(NEW)-'reversed_by_change_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'reversed_by_change_id') AND EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.reversed_by_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.payload->>'sourceChangeId'=OLD.change_id::text AND f.status='approved') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'loss-of-control evidence is immutable; propose its independently approved correction';
 ELSIF TG_OP='DELETE' THEN RAISE EXCEPTION 'loss-of-control evidence cannot be deleted'; END IF;
 IF NOT(NEW.excluded_subsidiary_ids ? NEW.subsidiary_id::text) OR NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=NEW.org_id AND s.id=NEW.elimination_subsidiary_id AND s.is_elimination) OR (NEW.retained_interest_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM subsidiary_ownership_interests p WHERE p.org_id=NEW.org_id AND p.id=NEW.retained_interest_id AND p.subsidiary_id=NEW.subsidiary_id AND p.parent_subsidiary_id=NEW.parent_subsidiary_id AND p.method=NEW.retained_method AND p.effective_from=NEW.effective_on+1)) THEN RAISE EXCEPTION 'loss-of-control entities and retained interest must match the approved ownership scope'; END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting_books b WHERE b.id=NEW.book_id AND b.org_id=NEW.org_id AND b.is_primary AND b.posts_gl AND b.is_active) OR NOT EXISTS(SELECT 1 FROM accounting_periods p WHERE p.id=NEW.period_id AND p.org_id=NEW.org_id AND NEW.effective_on BETWEEN p.starts_on AND p.ends_on) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.excluded_subsidiary_ids) child(id) WHERE NOT EXISTS(SELECT 1 FROM subsidiaries s WHERE s.id=child.id::uuid AND s.org_id=NEW.org_id)) THEN RAISE EXCEPTION 'loss-of-control scope must reference this organization and accounting period'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(array_remove(ARRAY[NEW.parent_journal_entry_id,NEW.journal_entry_id],NULL)) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM journal_entries e WHERE e.org_id=NEW.org_id AND e.id=wanted.id AND e.book_id=NEW.book_id AND e.period_id=NEW.period_id AND e.status='posted')) THEN RAISE EXCEPTION 'loss-of-control journals must be posted in its accounting book and period'; END IF;
 IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=NEW.org_id AND f.id=NEW.change_id AND f.domain='consolidation' AND f.subject_id=NEW.interest_id AND f.status='approved') THEN RAISE EXCEPTION 'loss of control requires independent approval for this ownership interest'; END IF;
 IF NOT EXISTS(SELECT 1 FROM subsidiary_ownership_interests p WHERE p.org_id=NEW.org_id AND p.id=NEW.interest_id AND p.subsidiary_id=NEW.subsidiary_id AND p.parent_subsidiary_id=NEW.parent_subsidiary_id AND p.effective_to=NEW.effective_on) THEN RAISE EXCEPTION 'loss of control must close its ownership window at the approved date'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.control_loss_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
 IF TG_TABLE_NAME='journal_entries' THEN
  IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status<>'posted') AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=NEW.org_id AND loss.reversed_by_change_id IS NULL AND loss.book_id=NEW.book_id AND ( (NEW.posting_date<=loss.effective_on AND EXISTS(SELECT 1 FROM journal_lines l WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.id AND loss.excluded_subsidiary_ids ? l.subsidiary_id::text)) OR NEW.reverses_entry_id IN(SELECT jsonb_array_elements_text(loss.measurement->'sourceEntryIds')::uuid) OR NEW.reverses_entry_id IN(SELECT jsonb_array_elements_text(f.result->'entryIds')::uuid FROM financial_changes f WHERE f.org_id=loss.org_id AND f.id=loss.change_id) OR NEW.reverses_entry_id IN(SELECT (evidence->>'entryId')::uuid FROM jsonb_array_elements(loss.measurement->'manualEvidence') evidence))) THEN RAISE EXCEPTION 'this posting changes an approved disposal source; propose a correction from Accounting changes before changing the historical balances'; END IF;
  RETURN NEW;
 ELSIF TG_TABLE_NAME='consolidated_fx_rates' THEN
  IF EXISTS(SELECT 1 FROM consolidation_control_losses loss JOIN accounting_periods p ON p.org_id=loss.org_id AND p.id=OLD.period_id WHERE loss.org_id=OLD.org_id AND loss.reversed_by_change_id IS NULL AND p.starts_on<=loss.effective_on AND EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=loss.org_id AND loss.excluded_subsidiary_ids ? s.id::text AND s.base_currency=OLD.from_currency)) AND (TG_OP='DELETE' OR (NEW.current_rate,NEW.average_rate,NEW.historical_rate) IS DISTINCT FROM (OLD.current_rate,OLD.average_rate,OLD.historical_rate)) THEN RAISE EXCEPTION 'consolidated rates support an approved disposal; correct that disposal before changing its historical translation evidence'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.cost_layer_fill_subsidiary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.source_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer requires the legal entity of its source receipt movement',
      DETAIL = 'The source movement was not found, so ownership could not be derived.',
      HINT = 'Create the source movement before its cost layer.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_org_base_price_level()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.sandbox_of IS NOT NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.price_levels (org_id, code, name, is_base, is_active)
  VALUES (NEW.id, 'BASE', 'Base price', true, true);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.data_transfer_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF public.app_bypass_rls_active() AND current_setting('openbooks.amend',true)='on' THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='data_transfer_chunks' THEN
  IF TG_OP='DELETE' AND OLD.direction='output'
     AND EXISTS (SELECT 1 FROM public.data_transfer_jobs WHERE org_id=OLD.org_id AND id=OLD.job_id AND state='exporting') THEN
   RETURN OLD;
  END IF;
 ELSIF TG_TABLE_NAME='data_transfer_rows' THEN
  IF TG_OP='UPDATE' AND ROW(NEW.org_id,NEW.job_id,NEW.row_no,NEW.data) IS NOT DISTINCT FROM ROW(OLD.org_id,OLD.job_id,OLD.row_no,OLD.data) THEN
   RETURN NEW;
  END IF;
 END IF;
 RAISE EXCEPTION 'Transfer source and lifecycle evidence are immutable; create a new transfer for corrected source data.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.depreciation_evidence_attachment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.target_table = 'fixed_assets' and exists (
    select 1
      from depreciation_inputs i
      join depreciation_schedules s on s.id = i.schedule_id
     where i.org_id = old.org_id and i.evidence_file_id = old.file_id and s.asset_id = old.target_id
  ) then
    raise exception 'file attachment is retained by depreciation evidence';
  end if;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.depreciation_input_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  owning_asset uuid;
begin
  select s.asset_id into owning_asset
    from depreciation_schedules s
   where s.id = new.schedule_id and s.org_id = new.org_id;
  if owning_asset is null then
    raise exception 'depreciation input schedule must belong to the tenant';
  end if;
  if not exists (select 1 from files f where f.id = new.evidence_file_id and f.org_id = new.org_id and not f.is_inactive) then
    raise exception 'depreciation evidence file must be active and belong to the tenant';
  end if;
  if not exists (
    select 1 from file_attachments fa
     where fa.org_id = new.org_id and fa.file_id = new.evidence_file_id
       and fa.target_table = 'fixed_assets' and fa.target_id = owning_asset
  ) then
    raise exception 'depreciation evidence file must be attached to the owning fixed asset';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.depreciation_non_gl_recognition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  book_id uuid;
  subsidiary_id uuid;
BEGIN
  IF TG_OP <> 'INSERT' AND OLD.non_gl_recognized_at IS NOT NULL THEN
    IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF TG_OP = 'DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'recognized reporting-book depreciation is immutable; retain this line and rebuild only unrecognized schedule lines';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.non_gl_recognized_at IS NULL THEN RETURN NEW; END IF;

  -- A recognition completes an existing measurement, never rewrites a posted
  -- one or launders imported/GL evidence into the reporting-only path.
  IF NEW.posted_amount IS NULL OR NEW.posted_amount IS DISTINCT FROM NEW.planned_amount
     OR NEW.journal_entry_id IS NOT NULL OR NEW.source = 'imported'
     OR (TG_OP = 'UPDATE' AND OLD.posted_amount IS NOT NULL) THEN
    RAISE EXCEPTION 'reporting-book recognition requires its unrecognized planned amount and no GL journal';
  END IF;
  IF TG_OP = 'UPDATE' AND
     (to_jsonb(NEW) - ARRAY['posted_amount','non_gl_recognized_at','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['posted_amount','non_gl_recognized_at','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'recognize the existing depreciation measurement before proposing a separate correction';
  END IF;
  -- Branch: clone-authority-insert (0316). The deterministic clone replays
  -- recognized reporting-book history verbatim. The referenced book, asset
  -- and period rows may not be visible yet — bulk-copy order is not
  -- topological inside a reference cycle, so a row trigger cannot assume its
  -- parents were copied first (the deferred foreign keys validate them at
  -- commit instead) — and the target period may already be closed there, even
  -- though the recognition was valid where it was written. Skip the
  -- live-state revalidation below for the copied row: the shape checks above
  -- still ran, the CHECK constraints still apply, and the row keeps its
  -- source recognition instant verbatim instead of restamping it. INSERT-only:
  -- an UPDATE or DELETE under the authority still runs every check below.
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  SELECT b.id, a.subsidiary_id INTO book_id, subsidiary_id
    FROM public.depreciation_schedules s
    JOIN public.accounting_books b ON b.id = s.book_id AND b.org_id = s.org_id
    JOIN public.fixed_assets a ON a.id = s.asset_id AND a.org_id = s.org_id
    JOIN public.accounting_periods p ON p.id = NEW.period_id AND p.org_id = s.org_id
   WHERE s.id = NEW.schedule_id AND s.org_id = NEW.org_id
     AND b.is_active AND NOT b.posts_gl
     AND a.status NOT IN ('disposed', 'written_off')
   FOR SHARE OF b;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reporting-book recognition requires an active non-posting book and an active asset and period in the same organization';
  END IF;
  IF NEW.updated_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = NEW.updated_by AND u.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'depreciation recognition actor must belong to the same organization';
  END IF;
  PERFORM public.period_posting_fence(NEW.org_id, NEW.period_id, book_id);
  IF public.period_module_blocks_write(NEW.org_id, NEW.period_id, book_id, subsidiary_id, 'assets', false)
     OR public.period_module_blocks_write(NEW.org_id, NEW.period_id, book_id, subsidiary_id, 'gl', false) THEN
    RAISE EXCEPTION 'the accounting book is closed for depreciation; obtain an authorized period reopening before running depreciation';
  END IF;
  -- An operator cannot backdate the recognition timestamp used by reversal
  -- guards. The effective service period remains NEW.period_id.
  NEW.non_gl_recognized_at := clock_timestamp();
  NEW.updated_at := NEW.non_gl_recognized_at;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.document_correction_lineage_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  replacement record;
  source record;
BEGIN
  IF tg_op <> 'INSERT' THEN
    IF old.link_type = 'reverses'
       AND NOT openbooks_sandbox_wipe_allowed(old.org_id)
    THEN
      RAISE EXCEPTION
        'document correction lineage is immutable; retain the source and replacement';
    END IF;
    RETURN coalesce(new, old);
  END IF;

  IF new.link_type <> 'reverses' THEN
    RETURN new;
  END IF;

  SELECT id, org_id, kind, status, posted_entry_id
    INTO replacement
    FROM documents
   WHERE id = new.from_document_id
   FOR KEY SHARE;
  SELECT id, org_id, kind, status, posted_entry_id
    INTO source
    FROM documents
   WHERE id = new.to_document_id
   FOR KEY SHARE;

  IF replacement.id IS NULL OR source.id IS NULL
     OR replacement.org_id <> new.org_id
     OR source.org_id <> new.org_id
  THEN
    RAISE EXCEPTION
      'a correction source and replacement must belong to the same tenant';
  END IF;
  IF replacement.id = source.id THEN
    RAISE EXCEPTION 'a document cannot correct itself';
  END IF;
  IF replacement.kind <> source.kind THEN
    RAISE EXCEPTION
      'a correction must retain the source document kind';
  END IF;
  IF source.status NOT IN ('posted', 'voided') THEN
    RAISE EXCEPTION
      'only a posted or already-voided document can be the source of a correction';
  END IF;
  IF replacement.status <> 'draft'
     OR replacement.posted_entry_id IS NOT NULL
  THEN
    RAISE EXCEPTION
      'correction lineage must be established while the replacement is an unposted draft';
  END IF;
  RETURN new;
END
$function$

CREATE OR REPLACE FUNCTION public.document_line_immutability_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_old_document_id uuid;
  v_new_document_id uuid;
  v_old_org_id uuid;
  v_new_org_id uuid;
  v_old_found boolean := false;
  v_new_found boolean := false;
  v_old_status text;
  v_new_status text;
  v_old_kind text;
  v_new_kind text;
  v_parent record;
  v_sandbox_wipe boolean;
  v_trusted_replay boolean;
  v_payroll_commit text;
BEGIN
  v_old_document_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.document_id ELSE NULL END;
  v_new_document_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.document_id ELSE NULL END;
  v_old_org_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.org_id ELSE NULL END;
  v_new_org_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.org_id ELSE NULL END;

  -- Sandbox teardown is an explicit, tenant-scoped delete path. It runs before
  -- parent lookup because the teardown deliberately deletes children first and
  -- may encounter a parent that was already removed by an earlier pass.
  v_sandbox_wipe :=
    TG_OP = 'DELETE'
    AND (v_old_org_id IS NULL OR public.openbooks_sandbox_wipe_allowed(v_old_org_id));
  IF v_sandbox_wipe THEN
    RETURN OLD;
  END IF;

  -- Trusted replay runs before the parent lookup (moved here in 0148): the
  -- sandbox clone copies document lines before their documents, so a
  -- legitimately absent parent must not raise for a replay caller. The
  -- authority is unchanged — paired, transaction-local migration+amend — and
  -- ordinary writers still fall through to the lookup and freeze below. The
  -- parent row lock is not load-bearing for replay: frozen posted lines admit
  -- no concurrent ordinary writer on the same document.
  v_trusted_replay :=
    coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on';
  IF v_trusted_replay THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Lock every referenced parent in deterministic id order. The lookup uses
  -- the physical parent id first, then checks org_id explicitly so a line can
  -- never borrow a document from another tenant even while composite foreign
  -- keys are being upgraded on an older installation.
  FOR v_parent IN
    SELECT d.id, d.org_id, d.status, d.kind
      FROM public.documents d
     WHERE d.id IN (v_old_document_id, v_new_document_id)
     ORDER BY d.id
     FOR UPDATE
  LOOP
    IF v_parent.id = v_old_document_id THEN
      v_old_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_old_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_old_document_id, v_old_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_old_status := v_parent.status;
      v_old_kind := v_parent.kind;
    END IF;
    IF v_parent.id = v_new_document_id THEN
      v_new_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_new_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_new_document_id, v_new_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_new_status := v_parent.status;
      v_new_kind := v_parent.kind;
    END IF;
  END LOOP;

  IF v_old_document_id IS NOT NULL AND NOT v_old_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_old_document_id, v_old_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_new_document_id IS NOT NULL AND NOT v_new_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_new_document_id, v_new_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Payroll commit on an approved pay run (migration 0145). The engine sets
  -- `openbooks.payroll_commit` to the committing run's document id inside its
  -- commit transaction only, after the approval release, the commit-time
  -- fences, and both freshness re-checks have passed. Honored solely for that
  -- document's own lines, solely while its parent is an approved pay_run, and
  -- solely for the delete+insert pair a commit performs — UPDATE stays frozen.
  v_payroll_commit := coalesce(current_setting('openbooks.payroll_commit', true), '');
  IF (TG_OP = 'DELETE' OR TG_OP = 'INSERT') AND v_payroll_commit <> '' THEN
    IF TG_OP = 'DELETE'
       AND v_old_document_id::text = v_payroll_commit
       AND v_old_kind = 'pay_run' AND v_old_status = 'approved' THEN
      RETURN OLD;
    END IF;
    IF TG_OP = 'INSERT'
       AND v_new_document_id::text = v_payroll_commit
       AND v_new_kind = 'pay_run' AND v_new_status = 'approved' THEN
      RETURN NEW;
    END IF;
  END IF;

  IF v_old_document_id IS NOT NULL AND v_old_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its lines are immutable outside draft status',
      v_old_document_id, v_old_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF v_new_document_id IS NOT NULL AND v_new_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its lines are immutable outside draft status',
      v_new_document_id, v_new_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.document_line_tax_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_status text;
declare v_org uuid;
begin
  v_org := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(v_org) then return old; end if;
  select d.status into v_status
    from documents d join document_lines dl on dl.document_id = d.id
   where dl.id = case when tg_op = 'DELETE' then old.document_line_id else new.document_line_id end;
  if v_status <> 'draft'
     and coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'posted tax calculation evidence is immutable';
  end if;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.document_lines_total_line_refresh()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
        RETURN NULL;
    ELSIF tg_op = 'DELETE' THEN
        PERFORM public.refresh_document_totals_from_lines(old.document_id, old.org_id);
    ELSIF tg_op = 'UPDATE' THEN
        IF (old.document_id, old.org_id) IS DISTINCT FROM (new.document_id, new.org_id) THEN
            PERFORM public.refresh_document_totals_from_lines(old.document_id, old.org_id);
        END IF;
        PERFORM public.refresh_document_totals_from_lines(new.document_id, new.org_id);
    ELSE
        PERFORM public.refresh_document_totals_from_lines(new.document_id, new.org_id);
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_lines_total_line_tieout()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
        RETURN NULL;
    ELSIF tg_op = 'DELETE' THEN
        PERFORM public.assert_document_totals_match_lines(old.document_id, old.org_id);
    ELSIF tg_op = 'UPDATE' THEN
        IF (old.document_id, old.org_id) IS DISTINCT FROM (new.document_id, new.org_id) THEN
            PERFORM public.assert_document_totals_match_lines(old.document_id, old.org_id);
        END IF;
        PERFORM public.assert_document_totals_match_lines(new.document_id, new.org_id);
    ELSE
        PERFORM public.assert_document_totals_match_lines(new.document_id, new.org_id);
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_open_balance_amount(p_org uuid, p_entry uuid, p_currency text, p_status text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_count bigint;
  v_valid boolean;
  v_balance numeric;
BEGIN
  IF p_status = 'voided' OR p_entry IS NULL THEN RETURN NULL; END IF;
  SELECT count(jl.id),
         bool_and(jl.currency = p_currency),
         sum(abs(jl.txn_amount)) - coalesce(sum(ap.applied), 0)
    INTO v_count, v_valid, v_balance
    FROM public.journal_lines jl
    LEFT JOIN LATERAL (
      SELECT sum(CASE WHEN a.from_line_id = jl.id
                      THEN a.source_transaction_amount
                      ELSE a.target_transaction_amount END) AS applied
        FROM public.applications a
       WHERE a.org_id = p_org AND a.unapplied_at IS NULL
         AND (a.from_line_id = jl.id OR a.to_line_id = jl.id)
    ) ap ON true
   WHERE jl.entry_id = p_entry AND jl.org_id = p_org AND jl.is_open_item;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF v_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'document open-item currency mismatch: org %, posted entry %, expected currency %',
      p_org, p_entry, p_currency
      USING ERRCODE = '23514';
  END IF;
  RETURN v_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.documents_total_line_tieout()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM public.assert_document_totals_match_lines(new.id, new.org_id);
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.drop_ship_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP<>'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
      IF TG_OP='DELETE' THEN RETURN OLD; END IF;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'agency allocations are immutable; reverse and replace the document through its controlled workflow';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.financial_changes change JOIN public.document_lines line ON line.org_id=change.org_id AND line.id=NEW.document_line_id
    JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
    WHERE change.id=NEW.change_id AND change.org_id=NEW.org_id AND change.domain='sales' AND change.subject_id=NEW.sales_order_line_id AND change.status='applied'
      AND change.payload->>'controlsBeforeTransfer'='false' AND document.id=NEW.document_id AND document.kind=NEW.kind AND document.subsidiary_id=change.subsidiary_id)
    THEN RAISE EXCEPTION 'agency allocation must bind to its approved control judgment and native document'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.dunning_log_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if public.app_bypass_rls_active() then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if TG_OP = 'DELETE' then
    raise exception 'dunning_log is append-only: DELETE is refused; a rung''s lifecycle moves forward through staged/sent/failed/suppressed transitions only';
  end if;
  if TG_OP = 'INSERT' then
    return new;
  end if;
  if old.status = 'sent' or old.status = 'skipped' then
    raise exception 'dunning_log % rows are terminal delivery evidence and cannot be updated; failed and suppressed rows re-arm to staged, sent rows never move', old.status;
  end if;
  if old.status = 'staged' and new.status in ('sent', 'failed', 'suppressed') then
    return new;
  end if;
  if (old.status = 'failed' or old.status = 'suppressed') and new.status = 'staged' then
    return new;
  end if;
  raise exception 'dunning_log transition % to % is refused: the send attempt may move staged to sent/failed/suppressed, and the runner may re-arm failed/suppressed to staged', old.status, new.status;
end;
$function$

CREATE OR REPLACE FUNCTION public.employment_assignment_versions_employment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_employment uuid;
BEGIN
  SELECT employment_id INTO actual_employment FROM public.employment_assignments
    WHERE id = NEW.assignment_id AND org_id = NEW.org_id;
  IF actual_employment IS NULL THEN
    RAISE EXCEPTION 'employment_assignment_versions: assignment must exist in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF actual_employment IS DISTINCT FROM NEW.employment_id THEN
    RAISE EXCEPTION 'employment_assignment_versions: employment_id must match the assignment''s employment'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.employment_changes_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'employment_changes: evidence rows are immutable; record a new revision instead'
    USING ERRCODE = '23514';
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.employment_changes_provenance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_employment uuid;
BEGIN
  IF NEW.assignment_id IS NOT NULL THEN
    SELECT employment_id INTO actual_employment FROM public.employment_assignments
      WHERE id = NEW.assignment_id AND org_id = NEW.org_id;
    IF actual_employment IS NULL THEN
      RAISE EXCEPTION 'employment_changes: assignment must exist in the same organization'
        USING ERRCODE = '23514';
    END IF;
    IF actual_employment IS DISTINCT FROM NEW.employment_id THEN
      RAISE EXCEPTION 'employment_changes: assignment must belong to the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.employment_changes c
                   WHERE c.id = NEW.supersedes_id AND c.org_id = NEW.org_id
                     AND c.employment_id = NEW.employment_id) THEN
      RAISE EXCEPTION 'employment_changes: supersedes_id must name evidence for the same employment'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_deleted_role_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND
     ROW(OLD.user_id, OLD.org_id) IS NOT DISTINCT FROM ROW(NEW.user_id, NEW.org_id) THEN
    RETURN NULL;
  END IF;
  PERFORM public.assert_active_user_has_role(OLD.user_id, OLD.org_id);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_user_active_role_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM assert_active_user_has_role(NEW.id, NEW.org_id);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.entitlement_ledger_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE' then
    raise exception
      'entitlement_ledger is append-only; correct a balance with an adjustment movement';
  end if;
  if openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.pay_run_document_id is not null and exists (
    select 1 from pay_runs r
     where r.document_id = old.pay_run_document_id
       and r.run_status <> 'committed'
  ) then
    return old;
  end if;
  if old.kind = 'opening' and old.pay_run_document_id is null then
    if exists (
      select 1 from pay_stubs s
        join pay_runs r on r.document_id = s.pay_run_document_id and r.org_id = s.org_id
       where s.org_id = old.org_id
         and s.employee_party_id = old.employee_party_id
         and r.run_status = 'committed'
         and s.pay_date >= old.movement_date
    ) then
      raise exception
        'entitlement_ledger opening carry-in has already been consumed by a committed pay run; void that run before changing it';
    end if;
    return old;
  end if;
  raise exception
    'entitlement_ledger movements cannot be deleted once their pay run is committed';
end $function$

CREATE OR REPLACE FUNCTION public.extension_draft_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (NEW.id,NEW.org_id,NEW.created_by,NEW.extension_key,NEW.bundle,NEW.content_hash,NEW.base_version_id,NEW.reason,NEW.created_at)
     IS DISTINCT FROM
     (OLD.id,OLD.org_id,OLD.created_by,OLD.extension_key,OLD.bundle,OLD.content_hash,OLD.base_version_id,OLD.reason,OLD.created_at) THEN
    RAISE EXCEPTION 'Extension draft revisions are immutable; create a new revision';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='draft' AND NEW.status IN ('applied','discarded')) THEN
    RAISE EXCEPTION 'Invalid extension draft transition';
  END IF;
  IF (NEW.status='applied') IS DISTINCT FROM (NEW.applied_at IS NOT NULL) OR
     (OLD.status='applied' AND NEW.applied_at IS DISTINCT FROM OLD.applied_at) THEN
    RAISE EXCEPTION 'Invalid extension activation timestamp';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.field_ticket_evidence_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_row jsonb;
  v_org_id uuid;
  v_field_ticket_id uuid;
  v_evidence_id uuid;
BEGIN
  -- to_jsonb(NEW) is safe for either trigger relation.  Keep the casts here so
  -- malformed identifiers fail closed rather than being treated as absent.
  v_row := to_jsonb(NEW);
  v_org_id := (v_row ->> 'org_id')::uuid;
  v_field_ticket_id := (v_row ->> 'field_ticket_id')::uuid;

  IF NOT EXISTS (
    SELECT 1
      FROM public.field_tickets ft
     WHERE ft.document_id = v_field_ticket_id
       AND ft.org_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'field ticket evidence must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'field_ticket_signatures' THEN
    v_evidence_id := NULLIF(v_row ->> 'signature_file_id', '')::uuid;
    IF v_evidence_id IS NULL OR NOT EXISTS (
      SELECT 1
        FROM public.files f
       WHERE f.id = v_evidence_id
         AND f.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature file must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'field_ticket_signature_requests' THEN
    v_evidence_id := NULLIF(v_row ->> 'email_log_id', '')::uuid;
    IF v_evidence_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
        FROM public.email_log e
       WHERE e.id = v_evidence_id
         AND e.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature email evidence must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.field_ticket_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not exists (
    select 1 from documents d
     where d.id = new.document_id and d.org_id = new.org_id
       and d.kind = 'field_ticket'
  ) then
    raise exception 'field ticket header must extend a field_ticket document in the same organization'
      using errcode = '23514';
  end if;
  if new.foreman_party_id is not null and not exists (
    select 1 from parties p where p.id = new.foreman_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket foreman must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.charge_document_id is not null and not exists (
    select 1 from documents d where d.id = new.charge_document_id and d.org_id = new.org_id
  ) then
    raise exception 'field ticket charge document must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then
    raise exception 'field ticket submitter must belong to the same organization'
      using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.field_ticket_labor_snapshot_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_tickets ft
      JOIN documents d
        ON d.id = ft.document_id
       AND d.org_id = ft.org_id
       AND d.kind = 'field_ticket'
     WHERE ft.document_id = new.field_ticket_id
       AND ft.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'field ticket labor snapshot must belong to a Field Ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.captured_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.captured_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.superseded_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot superseding actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_at IS NOT NULL AND new.superseded_at < new.captured_at THEN
    RAISE EXCEPTION 'field ticket labor snapshot cannot be superseded before capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$function$

CREATE OR REPLACE FUNCTION public.field_ticket_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.customer_party_id is not null and not exists (
    select 1 from parties p
     where p.id = new.customer_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket customer policy must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.project_id is not null and not exists (
    select 1 from projects p
     where p.id = new.project_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket project policy must belong to the same organization'
      using errcode = '23514';
  end if;
  -- Effective-window exclusivity is owned by the
  -- field_ticket_policies_no_active_overlap exclusion constraint (0051),
  -- which stays correct under concurrent READ COMMITTED writers.
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.field_ticket_signature_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'field ticket signature requests are retained evidence';
  end if;
  if row(new.org_id, new.field_ticket_id, new.recipient, new.message,
         new.expires_at, new.token_digest, new.email_log_id,
         new.created_by, new.created_at)
     is distinct from
     row(old.org_id, old.field_ticket_id, old.recipient, old.message,
         old.expires_at, old.token_digest, old.email_log_id,
         old.created_by, old.created_at)
  then
    raise exception 'field ticket signature request evidence is immutable';
  end if;
  if old.responded_at is not null and new.responded_at is distinct from old.responded_at then
    raise exception 'field ticket signature response timestamp is immutable once set';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'field ticket signature revocation timestamp is immutable once set';
  end if;
  if old.sent_at is not null and new.sent_at is distinct from old.sent_at then
    raise exception 'field ticket signature delivery timestamp is immutable once set';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.financial_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  scrap_work_order_subsidiary_id uuid;
  scrap_posted_entry_id uuid;
  scrap_posted_journal_subsidiary_id uuid;
BEGIN
  IF TG_OP='DELETE' THEN
    IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'financial changes are immutable evidence; propose a correcting change';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM subsidiaries WHERE id=NEW.subsidiary_id AND org_id=NEW.org_id) THEN
    RAISE EXCEPTION 'financial change subsidiary must belong to the organization';
  END IF;
  IF TG_OP='INSERT' THEN
    -- Clone replay admission: the sandbox/sample-company clone replays
    -- immutable terminal history verbatim under the clone authority
    -- (openbooks.clone with openbooks.migration and openbooks.amend asserted
    -- together inside runClone's own RLS-bypass maintenance transaction).
    -- Admit that replayed INSERT while every ordinary session keeps the
    -- born-draft refusal below. UPDATE and DELETE of this history stay
    -- blocked: this admission returns only on the INSERT path.
    IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
    IF NEW.status <> 'draft' THEN RAISE EXCEPTION 'financial changes must start as draft'; END IF;
  END IF;
  -- Manufacturing restatement binding: one shared block. A
  -- manufacturing change is admitted only for the controlled scrap
  -- restatement, bound by value to the staged event, its work order, and
  -- the booking subsidiary. This block executes on the ordinary INSERT path
  -- above and, on UPDATE, on every allowed transition before the transition
  -- acceptance below, so an approved or applied restatement always carries
  -- the binding it was proposed with. The payload carries the
  -- engine-derived approval_required as immutable proposal evidence; no
  -- request, UI, or API surface supplies it, and the proposal payload is
  -- frozen after insert by the immutability check below.
  IF NEW.domain = 'manufacturing' AND (
       TG_OP = 'INSERT'
       OR (OLD.status = 'draft' AND NEW.status = 'pending')
       OR (OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected'))
       OR (OLD.status = 'approved' AND NEW.status = 'applied')) THEN
    IF NEW.operation <> 'scrap_snapshot_restatement' THEN
      RAISE EXCEPTION 'manufacturing financial changes admit only the scrap_snapshot_restatement operation, not %', NEW.operation;
    END IF;
    IF NEW.payload IS NULL OR jsonb_typeof(NEW.payload) <> 'object' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must carry an object payload binding the event, work order, subsidiary, and approval flag';
    END IF;
    IF NOT (NEW.payload ? 'event_id')
      OR NOT (NEW.payload ? 'work_order_id')
      OR NOT (NEW.payload ? 'subsidiary_id')
      OR NOT (NEW.payload ? 'requiredSubsidiaryIds') THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind event_id, work_order_id, subsidiary_id, and requiredSubsidiaryIds in the payload';
    END IF;
    IF jsonb_typeof(NEW.payload -> 'requiredSubsidiaryIds') <> 'array'
      OR jsonb_typeof(NEW.payload -> 'approval_required') <> 'boolean' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind requiredSubsidiaryIds as an array and the engine-derived approval_required as a boolean';
    END IF;
    IF (NEW.payload ->> 'event_id') <> NEW.subject_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement subject must be the bound event';
    END IF;
    SELECT work_order.subsidiary_id, scrap_event.posted_entry_id
      INTO scrap_work_order_subsidiary_id, scrap_posted_entry_id
      FROM public.mfg_scrap_events scrap_event
      JOIN public.mfg_work_orders work_order
        ON work_order.org_id = scrap_event.org_id
       AND work_order.id = scrap_event.work_order_id
     WHERE scrap_event.org_id = NEW.org_id
       AND scrap_event.id = NEW.subject_id
       AND scrap_event.work_order_id::text = (NEW.payload ->> 'work_order_id');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'manufacturing scrap restatement must bind the same-organization event, its work order, and that work order''s subsidiary';
    END IF;
    -- Subsidiary equality: the restatement books exactly the work order's
    -- subsidiary — work order, change row, payload, and the sole
    -- requiredSubsidiaryIds element are one value. A null work-order
    -- subsidiary authorizes nothing and is refused by name.
    IF scrap_work_order_subsidiary_id IS NULL THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % is refused: work order % carries no subsidiary, and a restatement requires a non-null authoritative work-order subsidiary', NEW.subject_id, (NEW.payload ->> 'work_order_id');
    END IF;
    IF scrap_work_order_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % must book the work order''s subsidiary %, not %', NEW.subject_id, scrap_work_order_subsidiary_id, NEW.subsidiary_id;
    END IF;
    IF (NEW.payload ->> 'subsidiary_id') IS DISTINCT FROM NEW.subsidiary_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % payload subsidiary % must equal the booking subsidiary %', NEW.subject_id, (NEW.payload ->> 'subsidiary_id'), NEW.subsidiary_id;
    END IF;
    IF (NEW.payload -> 'requiredSubsidiaryIds') <> jsonb_build_array(NEW.subsidiary_id::text) THEN
      RAISE EXCEPTION 'manufacturing scrap restatement requiredSubsidiaryIds must be exactly the booking subsidiary';
    END IF;
    -- Posted/unposted binding on the staged event. A posted event must
    -- point at a same-organization journal entry booked to the exact bound
    -- subsidiary; an unposted event carries no journal evidence at all, so
    -- any fabricated journal key in its payload is refused by name.
    IF scrap_posted_entry_id IS NOT NULL THEN
      SELECT journal_entry.subsidiary_id
        INTO scrap_posted_journal_subsidiary_id
        FROM public.journal_entries journal_entry
       WHERE journal_entry.org_id = NEW.org_id
         AND journal_entry.id = scrap_posted_entry_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % references posted entry % which has no same-organization journal entry; reconcile the posted entry through the controlled accounting evidence correction workflow before retrying the restatement, without posting a duplicate entry, reversing the entry, rewriting the event, or fabricating journal evidence', NEW.subject_id, scrap_posted_entry_id;
      END IF;
      IF scrap_posted_journal_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % posted entry % books subsidiary %, not the bound booking subsidiary %', NEW.subject_id, scrap_posted_entry_id, scrap_posted_journal_subsidiary_id, NEW.subsidiary_id;
      END IF;
    ELSE
      IF (NEW.payload ? 'posted_entry_id')
        OR (NEW.payload ? 'journal_entry_id')
        OR (NEW.payload ? 'entry_id') THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for unposted event % must not carry journal evidence; payload keys posted_entry_id, journal_entry_id, and entry_id are refused', NEW.subject_id;
      END IF;
    END IF;
  END IF;
  IF TG_OP='INSERT' THEN
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'financial change proposal is immutable; create a new proposal';
  END IF;
  IF NOT ((OLD.status='draft' AND NEW.status='pending') OR
          (OLD.status='pending' AND NEW.status IN ('approved','rejected')) OR
          (OLD.status='approved' AND NEW.status='applied')) THEN
    RAISE EXCEPTION 'invalid financial change transition % -> %', OLD.status, NEW.status;
  END IF;
  IF OLD.status <> 'pending' AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
    RAISE EXCEPTION 'financial change approval cannot be rewritten';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fixed_asset_configuration_org_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  method_id uuid;
  account_ids uuid[];
begin
  if tg_table_name = 'asset_categories' then
    method_id := new.default_depreciation_method_id;
  elsif tg_table_name = 'fixed_assets' then
    method_id := new.depreciation_method_id;
    account_ids := array_remove(array[new.asset_account_id, new.accumulated_depreciation_account_id, new.depreciation_expense_account_id], null);
  elsif tg_table_name in ('depreciation_schedules', 'depreciation_book_policies') then
    method_id := new.depreciation_method_id;
  end if;
  if method_id is not null and not exists (
    select 1 from depreciation_methods m where m.id = method_id and m.org_id = new.org_id and m.is_active
  ) then
    raise exception 'depreciation method must be active and belong to the tenant';
  end if;
  if cardinality(account_ids) > 0 and exists (
    select 1 from unnest(account_ids) wanted(id)
     where not exists (select 1 from accounts a where a.id = wanted.id and a.org_id = new.org_id and a.is_active and not a.is_summary)
  ) then
    raise exception 'fixed asset account override must be an active postable account in the tenant';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.fulfillment_documents_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.stage = 'done' THEN
    RAISE EXCEPTION 'a completed pick list or shipment is final and cannot be changed'
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT kind INTO document_kind
    FROM public.documents WHERE id = NEW.document_id AND org_id = NEW.org_id;
  IF document_kind IS DISTINCT FROM 'pick_list' AND document_kind IS DISTINCT FROM 'shipment' THEN
    RAISE EXCEPTION 'fulfilment detail belongs to a pick list or shipment, not a %', coalesce(document_kind, 'missing document')
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (
       NEW.carrier_id IS NOT NULL OR NEW.carrier_service IS NOT NULL OR NEW.tracking_number IS NOT NULL
       OR NEW.ship_to_address IS NOT NULL OR NEW.sales_fulfillment_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick list carries no carrier, tracking, ship-to address or fulfilment; those belong to its shipment'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.stage = 'done' AND (
       NEW.carrier_id IS NULL OR NEW.carrier_service IS NULL OR NEW.sales_fulfillment_id IS NULL) THEN
    RAISE EXCEPTION 'a completed shipment names its carrier, service and sales fulfilment'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fulfillment_lines_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  line_document uuid;
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft'
       OR NOT EXISTS (SELECT 1 FROM public.document_lines WHERE id = OLD.line_id AND org_id = OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment line detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT d.kind, d.status INTO document_kind, document_status
    FROM public.documents d WHERE d.id = NEW.document_id AND d.org_id = NEW.org_id;
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.line_id, NEW.org_id, NEW.document_id, NEW.sales_order_line_id, NEW.pick_line_id, NEW.lot_id, NEW.serial_id)
       IS DISTINCT FROM
       (OLD.line_id, OLD.org_id, OLD.document_id, OLD.sales_order_line_id, OLD.pick_line_id, OLD.lot_id, OLD.serial_id) THEN
      RAISE EXCEPTION 'only the carton of a fulfilment line can change'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    IF NEW.carton IS DISTINCT FROM OLD.carton AND document_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'cartons can change only while the shipment is a draft'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    RETURN NEW;
  END IF;
  SELECT document_id INTO line_document
    FROM public.document_lines WHERE id = NEW.line_id AND org_id = NEW.org_id;
  IF line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'fulfilment line detail must sit on the line''s own document'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (NEW.pick_line_id IS NOT NULL OR NEW.carton IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick-list line names no pick line and no carton'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.pick_line_id IS NULL THEN
    RAISE EXCEPTION 'a shipment line names the pick line it ships'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.funds_restriction_class_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_line_count bigint;
  v_code text;
begin
  if new.restriction_class is distinct from old.restriction_class then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id and l.extra_dims->>'fund' = old.id::text
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      select code into v_code from public.segment_values
       where org_id = old.org_id and id = old.id;
      raise exception 'fund % restriction class cannot change while % posted journal lines carry it',
        coalesce(v_code, old.id::text), v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.goods_tax_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE document_state text; owner uuid; current_org uuid;
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'goods tax calculation evidence is immutable; replace the draft line through its native document editor'; END IF;
  IF TG_OP='DELETE' THEN
    SELECT d.status INTO document_state FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
      WHERE l.org_id=OLD.org_id AND l.id=OLD.document_line_id;
    IF document_state='draft' OR document_state IS NULL THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'posted goods tax evidence cannot be deleted; use the controlled document reversal workflow';
  END IF;
  SELECT d.status,d.subsidiary_id,d.org_id INTO document_state,owner,current_org FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
    WHERE l.org_id=NEW.org_id AND l.id=NEW.document_line_id;
  IF document_state<>'draft' OR owner IS DISTINCT FROM NEW.subsidiary_id OR current_org IS DISTINCT FROM NEW.org_id
    OR NEW.snapshot->>'subsidiaryId'<>NEW.subsidiary_id::text OR NEW.snapshot->>'fingerprint'<>NEW.fingerprint
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.registration_ids) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM public.tax_registrations r
      WHERE r.org_id=NEW.org_id AND r.id=wanted.id::uuid AND r.subsidiary_id=NEW.subsidiary_id))
    THEN RAISE EXCEPTION 'native goods tax evidence must bind to its draft invoice, selling entity and registrations'; END IF;
  RETURN NEW;
END $function$

