CREATE OR REPLACE FUNCTION public.hrm_checklist_execution_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
  IF NEW.design IS DISTINCT FROM OLD.design THEN
    RAISE EXCEPTION 'Checklist instructions are a snapshot. Start a new checklist from a published template instead.';
  END IF;
  IF (OLD.status IN ('done','skipped') OR OLD.approval_status IN ('pending','approved')) AND
    (NEW.response,NEW.attachment_id,NEW.submitted_by,NEW.submitted_at) IS DISTINCT FROM (OLD.response,OLD.attachment_id,OLD.submitted_by,OLD.submitted_at) THEN
    IF OLD.approval_status='pending' AND OLD.status='pending' THEN
      RAISE EXCEPTION 'Submitted checklist evidence is immutable. Wait for a rejection before submitting corrected evidence.';
    END IF;
    RAISE EXCEPTION 'Reviewed or completed checklist evidence is immutable. Ask HR to cancel the open checklist and start a corrected one, or start a new checklist if it is closed.';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hrm_checklist_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE managed boolean;
BEGIN
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'hrm_process_templates' THEN
    managed := OLD.designer_managed;
    IF managed AND (NEW.kind,NEW.name,NEW.applies_to,NEW.is_active) IS DISTINCT FROM (OLD.kind,OLD.name,OLD.applies_to,OLD.is_active)
      AND current_setting('app.checklist_publish',true) IS DISTINCT FROM OLD.id::text THEN
      RAISE EXCEPTION 'Edit this checklist in HRM Checklist templates and publish its draft, or use Retire template there.';
    END IF;
    RETURN NEW;
  END IF;
  SELECT designer_managed INTO managed FROM public.hrm_process_templates
    WHERE org_id = COALESCE(NEW.org_id,OLD.org_id) AND id = COALESCE(NEW.template_id,OLD.template_id);
  IF managed AND current_setting('app.checklist_publish',true) IS DISTINCT FROM COALESCE(NEW.template_id,OLD.template_id)::text THEN
    RAISE EXCEPTION 'Edit steps in HRM Checklist templates and publish the complete draft instead.';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hrm_closure_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  identity_col text := TG_ARGV[0];
  idcol_val uuid;
  ev_txid bigint;
  ev_array jsonb;
  succ_at timestamptz;
  succ_n integer;
  elem jsonb;
  elem_n integer;
  expected_before jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.superseded_by IS NULL THEN
      RETURN NULL;
    END IF;
  ELSIF OLD.superseded_by IS NOT NULL OR NEW.superseded_by IS NULL THEN
    RETURN NULL;
  END IF;
  IF NEW.closed_by_change_id IS NULL THEN
    RAISE EXCEPTION '%: closing a version requires closed_by_change_id (the aggregate evidence event)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF identity_col = 'employment_id' THEN
    idcol_val := NEW.employment_id;
  ELSIF identity_col = 'assignment_id' THEN
    idcol_val := NEW.assignment_id;
  ELSE
    idcol_val := NEW.relationship_id;
  END IF;
  -- Real adjacent successor: exists, strictly newer, starts exactly here.
  -- PL/pgSQL EXECUTE never sets FOUND (docs 41.5.5 basic-statements), so the
  -- presence check reads ROW_COUNT: recorded_at is NOT NULL, but a NULL
  -- succ_at test would still be wrong (it confuses "no row" with data).
  EXECUTE format(
    'SELECT recorded_at FROM public.%I WHERE org_id = $1 AND %I = $2 AND version_no = $3',
    TG_TABLE_NAME, identity_col)
    INTO succ_at
    USING NEW.org_id, idcol_val, NEW.superseded_by;
  GET DIAGNOSTICS succ_n = ROW_COUNT;
  IF succ_n = 0 THEN
    RAISE EXCEPTION '%: superseded_by must name a real version_no of the same identity (no dangling pointers)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_by <= NEW.version_no THEN
    RAISE EXCEPTION '%: successor version_no must be strictly newer (rejects self and backwards)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF succ_at IS DISTINCT FROM NEW.recorded_until THEN
    RAISE EXCEPTION '%: successor recorded_at must equal the closed recorded_until (seamless handoff, no gap or overlap)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  -- Same-transaction aggregate event naming this exact closure. Plain
  -- SELECT ... INTO sets FOUND (unlike EXECUTE above), so IF NOT FOUND is
  -- correct here.
  SELECT c.change_txid, c.closed_versions INTO ev_txid, ev_array
    FROM public.employment_changes c
   WHERE c.id = NEW.closed_by_change_id AND c.org_id = NEW.org_id
     AND c.employment_id = NEW.employment_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION '%: closed_by_change_id must name an evidence event for the same employment', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF ev_txid IS DISTINCT FROM txid_current() THEN
    RAISE EXCEPTION '%: closure evidence must be written in the same transaction (change_txid must equal txid_current())', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  -- Exactly one element must name this closure: zero means the event does
  -- not evidence this close; two or more means the array double-counts one
  -- row and no single before-image can be authoritative. SELECT ... INTO
  -- would silently take the first of several, so count first.
  SELECT count(*) INTO elem_n FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', TG_TABLE_NAME::text, 'identity', idcol_val::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text);
  IF elem_n = 0 THEN
    RAISE EXCEPTION '%: evidence event must name this exact closure (table, identity, version_no, row_id) in closed_versions', TG_TABLE_NAME
      USING ERRCODE = '23514';
  ELSIF elem_n > 1 THEN
    RAISE EXCEPTION '%: evidence event names this closure more than once (duplicate closed_versions entries)', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  SELECT e INTO elem FROM jsonb_array_elements(ev_array) AS e
   WHERE e @> jsonb_build_object(
      'table', TG_TABLE_NAME::text, 'identity', idcol_val::text,
      'version_no', NEW.version_no, 'row_id', NEW.id::text)
   LIMIT 1;
  -- Exact prior image, full row, no column subtracted: on UPDATE the element
  -- must carry OLD as it stood before this close. The closing transition
  -- only ever fires from a live row, so OLD's closing columns are NULL on
  -- both sides, and the volatile audit columns are OLD's own prior touch —
  -- nothing needs excluding and the comment cannot overclaim. On INSERT of
  -- an already-closed row there is no OLD: the element must carry NEW as
  -- written (imported-image semantics, clearly separated from UPDATE).
  -- Key-only matching would admit forged history with the right identifiers.
  IF TG_OP = 'INSERT' THEN
    expected_before := to_jsonb(NEW);
  ELSE
    expected_before := to_jsonb(OLD);
  END IF;
  IF NOT (elem ? 'before') OR (elem->'before' IS DISTINCT FROM expected_before) THEN
    RAISE EXCEPTION '%: evidence event must carry the exact before-image of this closure in closed_versions[].before', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hrm_compensation_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  changed text[];
BEGIN
  IF TG_TABLE_NAME = 'hrm_comp_events' THEN
    -- The event ledger is evidence: updates refused on every path, deletes
    -- only on the governed amend path — record a new event instead of
    -- editing one.
    IF TG_OP = 'UPDATE' THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: % rows are append-only — record a new event instead of editing one', TG_TABLE_NAME
        USING ERRCODE = '25001';
    END IF;
    IF TG_OP = 'DELETE'
       AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path', TG_TABLE_NAME
        USING ERRCODE = '25001';
    END IF;
    RETURN OLD;
  END IF;
  -- Versioned SHOULD-pay rows and decided cycle lines are history once
  -- superseded/decided: terminal rows are immutable except a pure audit
  -- touch (updated_at/updated_by), exactly like 0195 terminal rows.
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path — retire by closing, never by deleting', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    -- One branch per table: PL/pgSQL does not short-circuit AND, so a
    -- shared predicate touching OLD.effective_to would fail on tables
    -- without that column. Each branch names only its own columns.
    IF TG_TABLE_NAME = 'hrm_pay_bands' THEN
      IF OLD.effective_to IS NOT NULL THEN
        changed := ARRAY(
          SELECT key FROM jsonb_each(to_jsonb(NEW)) AS n(key, value)
          WHERE (to_jsonb(OLD) -> n.key) IS DISTINCT FROM n.value);
        changed := ARRAY(SELECT c FROM unnest(changed) AS c WHERE c NOT IN ('updated_at', 'updated_by'));
        IF cardinality(changed) > 0 THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a closed pay band is history — open a new version instead of editing %', array_to_string(changed, ', ')
            USING ERRCODE = '25001';
        END IF;
      END IF;
    ELSIF TG_TABLE_NAME = 'hrm_comp_cycle_lines' THEN
      IF OLD.status IN ('approved', 'rejected', 'pushed') THEN
        changed := ARRAY(
          SELECT key FROM jsonb_each(to_jsonb(NEW)) AS n(key, value)
          WHERE (to_jsonb(OLD) -> n.key) IS DISTINCT FROM n.value);
        changed := ARRAY(SELECT c FROM unnest(changed) AS c
          WHERE c NOT IN ('updated_at', 'updated_by', 'status', 'approver_party_id', 'decided_at', 'reason', 'pushed_rate_id', 'revision'));
        IF OLD.status = 'pushed' AND (to_jsonb(NEW) ->> 'status') IS DISTINCT FROM 'pushed' THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a pushed line already moved payroll — reverse through a new cycle, never by reopening'
            USING ERRCODE = '25001';
        END IF;
        IF cardinality(changed) > 0 THEN
          RAISE EXCEPTION 'openbooks:immutable_evidence: a decided line is evidence — reopen it through the service instead of editing %', array_to_string(changed, ', ')
            USING ERRCODE = '25001';
        END IF;
      END IF;
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.hrm_compensation_plans_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- A published equity figure is evidence, not a draft: updates refused on
  -- every path, deletes only on the governed amend path — compute a new
  -- snapshot instead of editing one.
  IF TG_TABLE_NAME = 'hrm_pay_gap_snapshots' AND TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows are frozen — compute a new snapshot instead of editing one', TG_TABLE_NAME
      USING ERRCODE = '25001';
  END IF;
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.amend', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'openbooks:immutable_evidence: % rows delete only on the governed amend path', TG_TABLE_NAME
      USING ERRCODE = '25001';
