CREATE OR REPLACE FUNCTION public.je_check_posted_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_sum numeric(19,4);
  v_bad record;
  v_fx record;
begin
  if new.status <> 'posted' then return null; end if;
  select coalesce(sum(amount), 0) into v_sum
    from journal_lines
   where entry_id = new.id and org_id = new.org_id;
  if v_sum <> 0 then
    raise exception 'posted journal entry % does not balance (sum = %)', new.id, v_sum
      using errcode = '23514';
  end if;
  select subsidiary_id, sum(amount) as total into v_bad
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id having sum(amount) <> 0 limit 1;
  if found then
    raise exception 'posted journal entry % does not balance for subsidiary % (sum = %)',
      new.id, v_bad.subsidiary_id, v_bad.total using errcode = '23514';
  end if;
  select subsidiary_id,
         sum(abs(amount - round(txn_amount * fx_rate, 4))) as deviation,
         count(*) as lines,
         count(*) * 0.00005 as bound into v_fx
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id
  having sum(abs(amount - round(txn_amount * fx_rate, 4))) > count(*) * 0.00005 limit 1;
  if found then
    raise exception 'posted journal entry % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): correct through the ledger API by posting a reversal and reposting instead of editing history',
      new.id, v_fx.subsidiary_id, v_fx.deviation, v_fx.lines, v_fx.bound using errcode = '23514';
  end if;
  if (select count(*) from journal_lines where entry_id = new.id and org_id = new.org_id) < 2 then
    raise exception 'posted journal entry % must contain at least two lines', new.id
      using errcode = '23514';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.je_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_module text;
  v_replay_auth uuid;
begin
  -- Branch: journal-entry-delete (sandbox-wipe passthrough, posted/reversed delete fence).
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    -- Append-only (0380): a posted or reversed entry cannot be deleted, with
    -- no session-flag escape. Corrections reverse and repost; they never
    -- remove history.
    if old.status <> 'draft' then
      raise exception 'journal entry % is % and cannot be deleted', old.id, old.status;
    end if;
    perform period_posting_fence(old.org_id, old.period_id, old.book_id);
    -- G5 (0338, restored in 0400): the delete fence is soft-close-aware
    -- like its sibling update branches. period_module_is_closed is true
    -- only for state = 'closed', so it let soft_closed deletes through,
    -- contradicting 0246's rule that a soft close fences posting the same
    -- way a hard close does.
    if period_module_blocks_write(old.org_id, old.period_id, old.book_id,
         nullif(to_jsonb(old)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
      raise exception 'period is closed for GL posting';
    end if;
    return old;
  end if;

  -- Branch: posted-immutability (append-only: the only exit from posted is
  -- the evidenced reversal below; the amend same-status replay is gone by
  -- design and intentionally has no branch). The refusal names the remedy,
  -- which exists: corrections append a reversal through the ledger API
  -- (postEntry + markEntryReversed).
  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'journal entry % is posted and immutable: corrections append a reversal through the ledger API instead of editing history', old.id;
  end if;
  -- A posted entry may only leave posted status through controlled reversal
  -- (posted -> reversed). Any other regression — in particular posted ->
  -- draft, which would silently suppress posted history from every
  -- posted-only reader — raises here. No product flow writes posted -> draft.
  if old.status = 'posted' and new.status <> 'reversed' then
    raise exception 'journal entry % is posted and can only be reversed, not set to %', old.id, new.status;
  end if;
  -- Branch: reversal-evidence (0166, restored in 0400). posted -> reversed
  -- retires history, so the economics must already be offset: no economic
  -- header change may accompany the flip (only the lifecycle stamp and
  -- row-audit columns may differ), and a posted mirror reversal must exist
  -- in the same org and book referencing this entry. Existence, not
  -- uniqueness: reversal of a reversal and re-correction generations stay
  -- legal.
  if old.status = 'posted' and new.status = 'reversed' then
    if to_jsonb(old) - 'status' - 'updated_at' - 'updated_by' - 'posted_at'
       is distinct from
       to_jsonb(new) - 'status' - 'updated_at' - 'updated_by' - 'posted_at' then
      raise exception 'journal entry % is posted and can only be reversed without other changes', old.id;
    end if;
    if not exists (
      select 1
        from journal_entries reversal
       where reversal.org_id = old.org_id
         and reversal.book_id = old.book_id
         and reversal.reverses_entry_id = old.id
         and reversal.status = 'posted'
         and public.openbooks_reversal_mirrors(old.org_id, old.id, reversal.id)
    ) then
      raise exception 'journal entry % cannot be reversed without a posted mirror reversal in the same book', old.id;
    end if;
    return new;
  end if;
  -- Branch: reversed-immutable.
  if old.status = 'reversed' then
    raise exception 'journal entry % is reversed and immutable', old.id;
  end if;

  -- Branch: draft-post (f2/0168 owns the source-module recheck inside this block).
  if old.status = 'draft' and new.status = 'posted' then
    perform period_posting_fence(new.org_id, new.period_id, new.book_id);
    if period_module_blocks_write(new.org_id, new.period_id, new.book_id,
         nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       or exists (
         select 1 from journal_lines l
          where l.entry_id = new.id
            and l.org_id = new.org_id
            and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
              nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, 'gl',
              coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       ) then
      -- Branch: connector-replay-authorization (0439 admits a live durable
      -- grant through the closed-period fence). The application admits a
      -- closed-period connector replay only against a controller-recorded
      -- connector_replay_authorizations row covering the period, and names
      -- that row in openbooks.connector_replay_authorization
      -- (transaction-local) beside the flip. The named row is re-validated
      -- here — same organization, window open, period range covers this
      -- entry's period — so the durable grant opens the fence, never the
      -- flag alone. Anything else still raises below.
      begin
        v_replay_auth := nullif(current_setting('openbooks.connector_replay_authorization', true), '')::uuid;
      exception when invalid_text_representation then
        v_replay_auth := null;
      end;
      if not public.openbooks_connector_replay_authorized(new.org_id, v_replay_auth, new.period_id) then
        raise exception 'period is closed for GL posting';
      end if;
    end if;
    -- Module recheck (0168, restored in 0405): the app boundary validates
    -- the source document's own close module, but a module-only close can
    -- commit between that check and this flip while the GL predicate above
    -- stays open. Re-derive the module from the sourced document kind and
    -- recheck it here, under the shared fence taken above, so the flip is
    -- atomic with the complete module set. Sourceless journals and unmapped
    -- kinds resolve to GL/null and skip: GL was already checked above.
    if new.source_document_id is not null then
      select public.document_close_module(d.kind) into v_module
        from public.documents d
       where d.id = new.source_document_id;
      if v_module is not null and v_module <> 'gl'
         and (period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, v_module,
                coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              or exists (
                select 1 from journal_lines l
                 where l.entry_id = new.id
                   and l.org_id = new.org_id
                   and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                     nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, v_module,
                     coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              )) then
        raise exception 'period is closed for % posting', upper(v_module);
      end if;
    end if;
    new.posted_at := now();
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.jl_check_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_summary boolean;
  v_active boolean;
  v_ccy text;
begin
  -- Evidence-only stamps (0236) are not postings. The line satisfied the
  -- posting rules below when it was posted; recording cleared/reconciled
  -- evidence changes no posting-relevant field, so the question is not
  -- re-opened. The column set matches jl_guard() exactly: any UPDATE that
  -- touches anything else falls through to the full checks. Whether the
  -- stamp itself is a legal append-only transition stays jl_guard's call.
  if tg_op = 'UPDATE'
     and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
       = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
  then
    return new;
  end if;
  select is_summary, is_active, currency_restriction
    into v_summary, v_active, v_ccy
   from accounts
   where id = new.account_id and org_id = new.org_id
     for share;
  if not found then
    raise exception 'account % does not exist in organization %', new.account_id, new.org_id
      using errcode = '23503';
  end if;
  if v_summary then
    raise exception 'account % is a summary account and cannot be posted to', new.account_id;
  end if;
  if not v_active and coalesce(current_setting('openbooks.migration', true), 'off') <> 'on' then
    raise exception 'account % is inactive — reactivate the account or map the posting to an active account instead of posting to a deactivated one', new.account_id;
  end if;
  if v_ccy is not null and new.currency <> v_ccy then
    raise exception 'account % only accepts % postings', new.account_id, v_ccy;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.jl_check_required_dimensions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_key text; v_required jsonb;
begin
  select required_dimensions into v_required from accounts
   where id = new.account_id and org_id = new.org_id;
  for v_key in select jsonb_array_elements_text(coalesce(v_required, '[]'::jsonb)) loop
    if (case v_key
      when 'subsidiary' then new.subsidiary_id is null
      when 'department' then new.department_id is null
      when 'project' then new.project_id is null
      when 'location' then new.location_id is null
      when 'class' then new.class_id is null
      when 'party' then new.party_id is null
      else not (coalesce(new.extra_dims, '{}'::jsonb) ? v_key)
    end) then
      raise exception 'account % requires segment %', new.account_id, v_key using errcode = '23514';
    end if;
  end loop;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.jl_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_org uuid;
  v_period uuid;
  v_book uuid;
  v_old_status text;
  v_old_org uuid;
  v_old_period uuid;
  v_old_book uuid;
  v_line_org uuid;
  v_entry uuid;
  v_recon_same boolean;
  v_recon_statement_stamp boolean;
  v_recon_source_stamp boolean;
  v_source_same boolean;
  v_source_stamp boolean;
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  -- Tenant coherence (restored from 0038 in 0159): a line may only ever
  -- reference a journal entry of its OWN organization. On UPDATE the
  -- ORIGINAL parent is resolved too: the destination alone cannot vouch for
  -- the history the line leaves behind. A miss raises the foreign-key class
  -- error the ledger guards and the kernel-constraints canary rely on.
  if tg_op = 'DELETE' then
    v_line_org := old.org_id;
    v_entry := old.entry_id;
  else
    v_line_org := new.org_id;
    v_entry := new.entry_id;
  end if;
  select status, org_id, period_id, book_id
    into v_status, v_org, v_period, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if not found then
    raise exception 'journal entry % does not exist in organization %', v_entry, v_line_org
      using errcode = '23503';
  end if;
  if tg_op = 'UPDATE' then
    select status, org_id, period_id, book_id
      into v_old_status, v_old_org, v_old_period, v_old_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if not found then
      raise exception 'journal entry % does not exist in organization %', old.entry_id, old.org_id
        using errcode = '23503';
    end if;
    -- Original-parent immutability (0165, hardened in 0380): a line that
    -- leaves posted or reversed history for a different entry or
    -- organization is refused, with no session-flag escape. Evidence-only
    -- stamps never move lines, so any such move is a history rewrite.
    if v_old_status is distinct from 'draft'
       and (new.entry_id is distinct from old.entry_id
            or new.org_id is distinct from old.org_id) then
      raise exception 'lines of a % journal entry are immutable', v_old_status;
    end if;
  end if;
  if v_status is distinct from 'draft' then
    -- Branch: clone-authority-insert (0316, restored in 0400). The
    -- deterministic clone replays posted history verbatim into target
    -- periods that may already be closed there; the immutability raise
    -- below would refuse the copy even though the history was valid where
    -- it was written. Under the clone authority an INSERT carries that
    -- history across, still subject to the tenant-coherent parent lookup
    -- above and to every balance and account guard. UPDATE and DELETE fall
    -- through and stay blocked exactly as before. This needs no amend
    -- escape: the authority is the conjunction of four GUCs only the clone
    -- transaction holds.
    if tg_op = 'INSERT' and public.openbooks_clone_authority() then
      return new;
    end if;
    -- Bank-reconciliation sign-off stamps reconciled_at / reconciliation_id
    -- on posted lines. That is bookkeeping metadata, but it is still permanent
    -- financial-control evidence: it may only transition once from entirely
    -- unset to an extant unsigned reconciliation that already claims the line.
    -- Clearing, retargeting, or partially stamping the evidence is forbidden.
    -- Source-cleared evidence (0158) follows the same append-only rule: the
    -- mirror records the source system's cleared marker once, and a
    -- source-evidenced sign-off stamps only lines already carrying it.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
         = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
    then
      v_recon_same := new.reconciled_at is not distinct from old.reconciled_at
        and new.reconciliation_id is not distinct from old.reconciliation_id;
      v_source_same := new.source_cleared_date is not distinct from old.source_cleared_date
        and new.source_cleared_connector is not distinct from old.source_cleared_connector;
      if v_recon_same and v_source_same then
        return new;
      end if;
      v_recon_statement_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
        )
        and exists (
          select 1
            from reconciliation_matches m
           where m.reconciliation_id = new.reconciliation_id
             and m.journal_line_id = new.id
             and m.org_id = new.org_id
        );
      v_recon_source_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and new.source_cleared_date is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
             and r.evidence_kind = 'source'
        );
      v_source_stamp :=
        old.source_cleared_date is null
        and old.source_cleared_connector is null
        and new.source_cleared_date is not null
        and new.source_cleared_connector is not null
        and length(btrim(new.source_cleared_connector)) > 0;
      if (v_recon_same or v_recon_statement_stamp or v_recon_source_stamp)
         and (v_source_same or v_source_stamp) then
        return new;
      end if;
      raise exception 'journal-line reconciliation evidence is append-only';
    end if;
    -- Party-attribution moves (0380): the governed party-merge path
    -- re-points an absorbed party on posted lines. That changes NO amount,
    -- account, subsidiary, currency, or memo — party_id is the only column
    -- that may differ — and the move is refused when the period is closed
    -- for GL posting. There is no session-flag escape.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'party_id' = to_jsonb(old) - 'party_id'
       and new.party_id is distinct from old.party_id
    then
      if period_module_blocks_write(v_org, v_period, v_book,
           nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
           coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
        raise exception 'period is closed for GL posting';
      end if;
      return new;
    end if;
    -- Append-only (0380): the amend re-materialization branch is gone. A
    -- posted or reversed line admits clone replay, reconciliation-evidence
    -- stamps and party-attribution moves above; everything else is immutable.
    raise exception 'lines of a % journal entry are immutable', v_status;
  end if;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.journal_lines_check_fx_residual_entries(p_entry_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_bad_org uuid;
  v_bad_entry uuid;
  v_bad_subsidiary uuid;
  v_bad_deviation numeric(19, 4);
  v_bad_lines integer;
  v_bad_bound numeric;
begin
  -- One re-sum per touched (org, entry, subsidiary) group, not per line.
  -- Drafts are skipped: they post through je_check_posted_balance below.
  select l.org_id, l.entry_id, l.subsidiary_id,
         sum(abs(l.amount - round(l.txn_amount * l.fx_rate, 4))),
         count(*), count(*) * 0.00005
    into v_bad_org, v_bad_entry, v_bad_subsidiary, v_bad_deviation, v_bad_lines, v_bad_bound
    from unnest(p_entry_ids) t(entry_id)
    join journal_lines l on l.entry_id = t.entry_id
    join journal_entries e on e.id = t.entry_id
   where e.status is distinct from 'draft'
   group by l.org_id, l.entry_id, l.subsidiary_id
  having sum(abs(l.amount - round(l.txn_amount * l.fx_rate, 4))) > count(*) * 0.00005
   limit 1;
  if found then
    raise exception 'journal entry % in organization % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): correct through the ledger API by posting a reversal and reposting instead of editing history',
      v_bad_entry, v_bad_org, v_bad_subsidiary, v_bad_deviation, v_bad_lines, v_bad_bound
      using errcode = '23514';
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.journal_lines_lock_nonprofit_framework()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if coalesce(new.extra_dims, '{}'::jsonb) ? 'fund' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || new.org_id::text, 0)
    );
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.journal_primary_book_history_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  primary_ids uuid[];
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN new;
  END IF;
  SELECT array_agg(id) INTO primary_ids FROM (
    SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
      ORDER BY id FOR SHARE
  ) authority;
  -- A concurrent empty-org promotion can demote the row seen by the first
  -- statement while its lock waits. Take a fresh READ COMMITTED snapshot to
  -- resolve the successor, instead of proceeding without an authority fence.
  IF coalesce(cardinality(primary_ids), 0) = 0 THEN
    SELECT array_agg(id) INTO primary_ids FROM (
      SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
        ORDER BY id FOR SHARE
    ) authority;
  END IF;
  IF coalesce(cardinality(primary_ids), 0) <> 1 THEN
    RAISE EXCEPTION 'accounting history creation requires exactly one primary accounting book'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.landed_cost_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'landed-cost allocation evidence is append-only';
  END IF;
  IF OLD.journal_entry_id IS NULL
     AND NEW.journal_entry_id IS NOT NULL
     AND (to_jsonb(NEW) - 'journal_entry_id' - 'updated_at' - 'updated_by')
       = (to_jsonb(OLD) - 'journal_entry_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'landed-cost allocation evidence is immutable';
END
$function$

CREATE OR REPLACE FUNCTION public.landed_cost_voucher_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_status text;
  parent_org uuid;
BEGIN
  SELECT status, org_id
    INTO parent_status, parent_org
    FROM landed_cost_vouchers
   WHERE id = coalesce(NEW.voucher_id, OLD.voucher_id);
  IF TG_OP = 'DELETE' AND parent_status IS NULL THEN RETURN OLD; END IF;
  IF parent_status IS NULL
     OR parent_org IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'landed-cost target must reference a tenant-owned voucher';
  END IF;
  IF parent_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of a posted landed-cost voucher are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.layer_consumption_fill_subsidiary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer consumption requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its consumptions.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lease_agreement_revision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'draft' THEN RAISE EXCEPTION 'commenced lease agreements are retained; use a termination or correcting change'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.org_id<>NEW.org_id OR OLD.subsidiary_id<>NEW.subsidiary_id OR OLD.id<>NEW.id THEN
    RAISE EXCEPTION 'lease organization and legal entity are immutable';
  END IF;
  IF OLD.status='draft' THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW)-ARRAY['description','custom','updated_at','updated_by']) IS NOT DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['description','custom','updated_at','updated_by']) THEN RETURN NEW; END IF;
  IF NEW.revision<>OLD.revision+1 OR NEW.last_change_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM financial_changes c WHERE c.id=NEW.last_change_id AND c.org_id=NEW.org_id
      AND c.domain='lease' AND c.subject_id=NEW.id AND c.status='approved') THEN
    RAISE EXCEPTION 'changing a commenced lease requires an approved accounting change and a new revision';
  END IF;
  IF NEW.initial_liability IS DISTINCT FROM OLD.initial_liability OR NEW.initial_rou_asset IS DISTINCT FROM OLD.initial_rou_asset
     OR NEW.commencement_entry_id IS DISTINCT FROM OLD.commencement_entry_id OR NEW.commencement_on<>OLD.commencement_on
     OR NEW.book_id IS DISTINCT FROM OLD.book_id OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'lease commencement history is immutable';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lease_schedule_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'lease schedules are retained; supersede future rows through an approved change'; END IF;
  IF (to_jsonb(NEW) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'lease schedule measurements are immutable; append a revision';
  END IF;
  IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id THEN
    IF OLD.accrual_posted_at IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM financial_changes c WHERE c.id=NEW.superseded_by_change_id AND c.org_id=OLD.org_id
        AND c.subject_id=OLD.lease_id AND c.domain='lease' AND c.status='approved') THEN
      RAISE EXCEPTION 'only unaccrued rows may be superseded by an approved change to this lease';
    END IF;
  END IF;
  IF (OLD.payment_posted_at IS NOT NULL AND (NEW.payment_posted_at IS DISTINCT FROM OLD.payment_posted_at OR NEW.payment_entry_id IS DISTINCT FROM OLD.payment_entry_id))
    OR (OLD.accrual_posted_at IS NOT NULL AND (NEW.accrual_posted_at IS DISTINCT FROM OLD.accrual_posted_at OR NEW.amortization_entry_id IS DISTINCT FROM OLD.amortization_entry_id))
    OR (OLD.superseded_by_change_id IS NOT NULL AND NEW IS DISTINCT FROM OLD) THEN
    RAISE EXCEPTION 'completed lease events cannot be changed';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nonprofit_frameworks_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_line_count bigint;
  v_org_id uuid;
begin
  if tg_op = 'DELETE' and pg_catalog.pg_trigger_depth() > 1 then
    return old;
  end if;

  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'UPDATE' and new.org_id is distinct from old.org_id then
    raise exception 'a nonprofit framework cannot be moved to another organization'
      using errcode = '23514';
  end if;

  -- Fund line inserts use the same transaction lock, so a framework change
  -- cannot pass its history check while a fund posting is still in flight.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || v_org_id::text, 0)
  );

  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.framework is distinct from old.framework) then
    select count(*) into v_line_count
      from public.journal_lines jl
      join public.journal_entries je
        on je.org_id = jl.org_id and je.id = jl.entry_id
     where jl.org_id = v_org_id
       and jl.extra_dims ? 'fund'
       and je.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'nonprofit framework cannot change or be removed while % posted fund-tagged journal lines exist; continue with the current framework or use a separate organization',
        v_line_count
        using errcode = '23514',
              constraint = 'nonprofit_frameworks_history_guard';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_criteria_is_valid(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  account_id text;
BEGIN
  IF jsonb_typeof(value) <> 'object'
     OR value->>'version' <> '2'
     OR octet_length(value::text) > 100000
     OR NOT openbooks_bank_rule_group_is_valid(value->'match') THEN
    RETURN false;
  END IF;
  IF value ? 'accountScope' THEN
    IF jsonb_typeof(value->'accountScope') <> 'array' THEN
      RETURN false;
    END IF;
    FOR account_id IN SELECT entry FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)
    LOOP
      IF account_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF (SELECT count(*) <> count(DISTINCT entry) FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_group_is_valid(value jsonb, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  rule jsonb;
  field_name text;
  operator_name text;
  scalar_value text;
  numeric_value numeric;
  lower_bound numeric;
  upper_bound numeric;
BEGIN
  IF depth > 4
     OR jsonb_typeof(value) <> 'object'
     OR value->>'combinator' NOT IN ('and', 'or')
     OR jsonb_typeof(value->'rules') <> 'array'
     OR jsonb_array_length(value->'rules') NOT BETWEEN 1 AND 40 THEN
    RETURN false;
  END IF;

  FOR rule IN SELECT element FROM jsonb_array_elements(value->'rules') AS elements(element)
  LOOP
    IF jsonb_typeof(rule) <> 'object' THEN
      RETURN false;
    END IF;
    IF rule ? 'rules' THEN
      IF NOT openbooks_bank_rule_group_is_valid(rule, depth + 1) THEN
        RETURN false;
      END IF;
      CONTINUE;
    END IF;

    field_name := rule->>'field';
    operator_name := rule->>'op';
    scalar_value := rule->>'value';

    IF field_name IN ('description', 'payee', 'anyText', 'reference') THEN
      IF operator_name NOT IN ('contains', 'notContains', 'equals', 'startsWith', 'endsWith', 'isBlank')
         OR (operator_name <> 'isBlank' AND (jsonb_typeof(rule->'value') <> 'string' OR btrim(scalar_value) = '' OR length(scalar_value) > 200)) THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'flow' THEN
      IF operator_name <> 'is' OR scalar_value NOT IN ('in', 'out', 'any') THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'source' THEN
      IF operator_name <> 'equals' OR jsonb_typeof(rule->'value') <> 'string'
         OR btrim(scalar_value) = '' OR length(scalar_value) > 40 THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'amount' THEN
      IF operator_name NOT IN ('eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'between') THEN
        RETURN false;
      END IF;
      IF operator_name = 'between' THEN
        IF jsonb_typeof(rule->'value') <> 'array'
           OR jsonb_array_length(rule->'value') <> 2
           OR jsonb_typeof(rule->'value'->0) <> 'number'
           OR jsonb_typeof(rule->'value'->1) <> 'number' THEN
          RETURN false;
        END IF;
        lower_bound := (rule->'value'->>0)::numeric;
        upper_bound := (rule->'value'->>1)::numeric;
        IF lower_bound < 0 OR upper_bound < lower_bound THEN
          RETURN false;
        END IF;
      ELSE
        IF jsonb_typeof(rule->'value') <> 'number' THEN
          RETURN false;
        END IF;
        numeric_value := scalar_value::numeric;
        IF numeric_value < 0 THEN
          RETURN false;
        END IF;
      END IF;
    ELSIF field_name = 'date' THEN
      IF operator_name = 'withinDays' THEN
        IF jsonb_typeof(rule->'value') <> 'number' OR scalar_value::numeric <= 0 THEN
          RETURN false;
        END IF;
      ELSIF operator_name IN ('on', 'before', 'after') THEN
        IF jsonb_typeof(rule->'value') <> 'string'
           OR scalar_value !~ '^\d{4}-\d{2}-\d{2}$'
           OR to_char(scalar_value::date, 'YYYY-MM-DD') <> scalar_value THEN
          RETURN false;
        END IF;
      ELSE
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_outcome_is_valid(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  line jsonb;
  portion jsonb;
  optional_id text;
  remainder_count integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object' OR octet_length(value::text) > 100000 THEN
    RETURN false;
  END IF;
  IF value->>'action' = 'exclude' THEN
    RETURN value = '{"action":"exclude"}'::jsonb;
  END IF;
  IF value->>'action' <> 'categorize'
     OR value->>'version' <> '2'
     OR value->>'mode' NOT IN ('auto', 'suggest')
     OR jsonb_typeof(value->'lines') <> 'array'
     OR jsonb_array_length(value->'lines') NOT BETWEEN 1 AND 20 THEN
    RETURN false;
  END IF;

  IF value ? 'partyId' AND coalesce(value->>'partyId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  IF value ? 'memo' AND (jsonb_typeof(value->'memo') <> 'string' OR btrim(value->>'memo') = '' OR length(value->>'memo') > 300) THEN
    RETURN false;
  END IF;

  FOR line IN SELECT element FROM jsonb_array_elements(value->'lines') AS elements(element)
  LOOP
    IF jsonb_typeof(line) <> 'object'
       OR coalesce(line->>'accountId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR jsonb_typeof(line->'portion') <> 'object' THEN
      RETURN false;
    END IF;
    portion := line->'portion';
    IF portion->>'kind' = 'remainder' THEN
      remainder_count := remainder_count + 1;
    ELSIF portion->>'kind' = 'percent' THEN
      IF jsonb_typeof(portion->'value') <> 'number'
         OR (portion->>'value')::numeric <= 0
         OR (portion->>'value')::numeric > 100 THEN
        RETURN false;
      END IF;
    ELSIF portion->>'kind' = 'fixed' THEN
      IF jsonb_typeof(portion->'value') <> 'number' OR (portion->>'value')::numeric <= 0 THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;

    FOREACH optional_id IN ARRAY ARRAY['partyId', 'departmentId', 'projectId', 'locationId', 'classId', 'taxCodeId']
    LOOP
      IF line ? optional_id
         AND coalesce(line->>optional_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF line ? 'description'
       AND (jsonb_typeof(line->'description') <> 'string' OR btrim(line->>'description') = '' OR length(line->>'description') > 200) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN remainder_count <= 1;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_statement_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF tg_op = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'imported bank statement lines are immutable';
  END IF;
  IF tg_op = 'INSERT' THEN
    RETURN new;
  END IF;
  IF to_jsonb(new)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by'
     <> to_jsonb(old)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by' THEN
    RAISE EXCEPTION 'imported bank statement content is immutable';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM reconciliation_matches m
      JOIN reconciliations r ON r.id = m.reconciliation_id
     WHERE m.statement_line_id = old.id
       AND m.org_id = old.org_id
       AND r.status = 'signed_off'
  ) OR EXISTS (
    SELECT 1
      FROM reconciliations r
     WHERE r.org_id = old.org_id
       AND r.account_id = old.account_id
       AND r.currency = old.currency
       AND r.status = 'signed_off'
       AND r.through_date >= old.posted_on
       AND old.match_status = 'excluded'
  ) THEN
    RAISE EXCEPTION 'signed-off bank statement evidence is immutable';
  END IF;
  IF new.match_status = 'matched'
     AND NOT EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'matched bank statement line requires reconciliation-match evidence';
  END IF;
  IF new.match_status <> 'matched'
     AND EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'bank statement line with match evidence must remain matched';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_gl_activity_entry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_old_in boolean;
  v_new_in boolean;
  v_old_month date;
  v_new_month date;
  v_old_book uuid;
  v_new_book uuid;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'INSERT' then
    if new.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(new.id, new.org_id, date_trunc('month', new.posting_date)::date, 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(old.id, old.org_id, date_trunc('month', old.posting_date)::date, -1);
    end if;
    return null;
  end if;
  v_old_in := old.status in ('posted', 'reversed');
  v_new_in := new.status in ('posted', 'reversed');
  v_old_month := date_trunc('month', old.posting_date)::date;
  v_new_month := date_trunc('month', new.posting_date)::date;
  v_old_book := old.book_id;
  v_new_book := new.book_id;
  if v_old_in and not v_new_in then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
  elsif v_new_in and not v_old_in then
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  elsif v_old_in and v_new_in and (v_old_month <> v_new_month or v_old_book is distinct from v_new_book) then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1, v_old_book);
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.openbooks_gl_activity_line()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_date date;
  v_org uuid;
  v_book uuid;
  v_month date;
  v_entry uuid;
  v_line_org uuid;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'UPDATE'
     and (new.entry_id, new.org_id) is distinct from (old.entry_id, old.org_id) then
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
        -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
    end if;
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = new.entry_id and org_id = new.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
        greatest(new.amount, 0), greatest(-new.amount, 0), 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    v_entry := old.entry_id;
    v_line_org := old.org_id;
  else
    v_entry := new.entry_id;
    v_line_org := new.org_id;
  end if;
  select status, posting_date, org_id, book_id
    into v_status, v_date, v_org, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if v_status is null or v_status not in ('posted', 'reversed') then
    return null;
  end if;
  v_month := date_trunc('month', v_date)::date;
  if tg_op in ('UPDATE', 'DELETE') then
    perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
      -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
      greatest(new.amount, 0), greatest(-new.amount, 0), 1);
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_ap_capture_source_blob()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM file_versions fv
    JOIN ap_capture_items ci ON ci.file_id = fv.file_id
    WHERE fv.id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'AP capture source blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_ap_capture_source_file()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = OLD.id) THEN
    RAISE EXCEPTION 'AP capture source files are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_ap_capture_source_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_file_id uuid;
BEGIN
  target_file_id := CASE WHEN TG_OP = 'INSERT' THEN NEW.file_id ELSE OLD.file_id END;
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = target_file_id) THEN
    RAISE EXCEPTION 'AP capture source versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_budget_line()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  row_data budget_lines%rowtype;
  scenario_org uuid;
  scenario_year integer;
  scenario_status text;
begin
  row_data := case when tg_op = 'DELETE' then old else new end;
  select org_id, fiscal_year, status
    into scenario_org, scenario_year, scenario_status
    from budget_scenarios where id = row_data.scenario_id;
  -- During an ON DELETE CASCADE, PostgreSQL removes the parent scenario before
  -- firing the child row's delete trigger. The line was already protected by
  -- the scenario's draft-only delete guard, so allow that cascade to finish.
  if tg_op = 'DELETE' and scenario_org is null then return old; end if;
  if scenario_org is null or scenario_org <> row_data.org_id then
    raise exception 'budget line scenario must belong to the tenant';
  end if;
  if scenario_status <> 'draft' then
    raise exception 'budget lines are immutable outside draft status';
  end if;
  if tg_op = 'DELETE' then return old; end if;

  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id and a.is_active and not a.is_summary
  ) then
    raise exception 'budget account must be an active posting account in the tenant';
  end if;
  -- Budgets plan the profit and loss only: the six P&L types of the single
  -- PNL_TYPES definition (engine records/account-types), the same set the
  -- worksheet, the import, the variances and the prior-actuals copy filter
  -- on. Refuse a balance-sheet account by name rather than writing a line
  -- the worksheet hides but the totals count.
  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id
       and a.type in ('income', 'income_other', 'cogs', 'expense', 'expense_other', 'expense_deferred')
  ) then
    raise exception 'budget account must be a profit-and-loss posting account in the tenant (income, income_other, cogs, expense, expense_other, expense_deferred)';
  end if;
  if not exists (
    select 1 from accounting_periods p
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment
  ) then
    raise exception 'budget period must belong to the scenario fiscal year and tenant';
  end if;
  -- A budget is pinned to one calendar: the org default. The worksheet, the
  -- totals, the import resolver and the copy mapping all read that calendar,
  -- so a line on any other calendar would be hidden yet counted.
  if not exists (
    select 1 from accounting_periods p
      join fiscal_calendars fc on fc.id = p.fiscal_calendar_id and fc.org_id = p.org_id
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment and fc.is_default
  ) then
    raise exception 'budget period must belong to the scenario fiscal year on the default fiscal calendar of the tenant';
  end if;
  if new.department_id is not null and not exists (
    select 1 from departments d where d.id = new.department_id and d.org_id = new.org_id
  ) then raise exception 'budget department must belong to the tenant'; end if;
  if new.project_id is not null and not exists (
    select 1 from projects p where p.id = new.project_id and p.org_id = new.org_id
  ) then raise exception 'budget project must belong to the tenant'; end if;
  if new.location_id is not null and not exists (
    select 1 from locations l where l.id = new.location_id and l.org_id = new.org_id
  ) then raise exception 'budget location must belong to the tenant'; end if;
  if new.class_id is not null and not exists (
    select 1 from classes c where c.id = new.class_id and c.org_id = new.org_id
  ) then raise exception 'budget class must belong to the tenant'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_budget_scenario()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'only draft budget scenarios may be deleted';
    end if;
    return old;
  end if;

  if not exists (
    select 1 from accounting_books b
     where b.id = new.book_id and b.org_id = new.org_id and b.is_active
  ) then
    raise exception 'budget scenario book must be active and belong to the tenant';
  end if;

  if tg_op = 'UPDATE' then
    if new.revision <> old.revision + 1 then
      raise exception 'budget scenario revision must increment by exactly one';
    end if;
    if old.status <> 'draft' and (
      new.name is distinct from old.name or
      new.description is distinct from old.description or
      new.book_id is distinct from old.book_id or
      new.fiscal_year is distinct from old.fiscal_year or
      new.kind is distinct from old.kind
    ) then
      raise exception 'only draft budget metadata may be edited';
    end if;
    -- The book and fiscal year pin the plan to one ledger and one period
    -- set: changing either under existing lines would silently reinterpret
    -- the whole plan. Refuse here as well as in the route so writers
    -- bypassing the API meet the same refusal.
    if (new.book_id is distinct from old.book_id or new.fiscal_year is distinct from old.fiscal_year)
       and exists (select 1 from budget_lines bl where bl.scenario_id = new.id and bl.org_id = new.org_id)
    then
      raise exception 'budget book and fiscal year are fixed once the budget has lines';
    end if;
    if new.status is distinct from old.status and not (
      (old.status = 'draft' and new.status in ('pending_approval', 'archived')) or
      (old.status = 'pending_approval' and new.status in ('draft', 'approved', 'archived')) or
      (old.status = 'approved' and new.status = 'archived')
    ) then
      raise exception 'invalid budget status transition: % -> %', old.status, new.status;
    end if;
  end if;

  if new.status in ('pending_approval', 'approved') and not exists (
    select 1 from budget_lines bl
     where bl.scenario_id = new.id and bl.org_id = new.org_id and bl.amount <> 0
  ) then
    raise exception 'a submitted or approved budget must contain at least one non-zero line';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then raise exception 'budget submitter must belong to the tenant'; end if;
  if new.approved_by is not null and not exists (
    select 1 from users u where u.id = new.approved_by and u.org_id = new.org_id
  ) then raise exception 'budget approver must belong to the tenant'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_guard_depreciation_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  posted boolean;
begin
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'depreciation input evidence is append-preserved';
  end if;

  select exists (
    select 1 from depreciation_schedule_lines
     where input_id = old.id and posted_amount is not null
  ) into posted;
  if posted then
    raise exception 'posted depreciation input evidence is immutable';
  end if;

  if old.voided_at is not null
     or new.voided_at is null
     or new.voided_by is null
     or new.org_id is distinct from old.org_id
     or new.schedule_id is distinct from old.schedule_id
     or new.period_id is distinct from old.period_id
     or new.kind is distinct from old.kind
     or new.manual_amount is distinct from old.manual_amount
     or new.production_units is distinct from old.production_units
     or new.memo is distinct from old.memo
     or new.evidence_file_id is distinct from old.evidence_file_id
     or new.supersedes_input_id is distinct from old.supersedes_input_id
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'depreciation input evidence may only be voided before posting';
  end if;
  return new;
end;
$function$

