CREATE OR REPLACE FUNCTION public.price_level_activation_maintenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Clone replay copies the source activation periods immediately after the
    -- price levels; creating a new period here would duplicate that evidence.
    IF public.openbooks_clone_authority() THEN
      RETURN NEW;
    END IF;
    -- A level born inactive was never offered: no period until activated.
    -- Otherwise the standing offer opens at -infinity (see 0327).
    IF NEW.is_active THEN
      INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
      VALUES (NEW.org_id, NEW.id, '-infinity'::date, now());
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.is_active AND NOT NEW.is_active THEN
    UPDATE public.price_level_activation_history
       SET active_to = current_date, closed_at = now(), updated_at = now()
     WHERE org_id = NEW.org_id AND price_level_id = NEW.id AND active_to IS NULL;
  ELSIF NOT OLD.is_active AND NEW.is_active THEN
    INSERT INTO public.price_level_activation_history (org_id, price_level_id, active_from, opened_at)
    SELECT NEW.org_id, NEW.id, current_date, now()
     WHERE NOT EXISTS (
       SELECT 1 FROM public.price_level_activation_history h
        WHERE h.org_id = NEW.org_id AND h.price_level_id = NEW.id AND h.active_to IS NULL
     );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.primary_book_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  source_org uuid;
  target_org uuid;
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    IF tg_op = 'DELETE' THEN RETURN old; END IF;
    RETURN new;
  END IF;
  IF tg_op = 'DELETE' THEN
    IF NOT old.is_primary OR public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    source_org := old.org_id;
  ELSIF tg_op = 'INSERT' THEN
    IF NOT new.is_primary THEN RETURN new; END IF;
    target_org := new.org_id;
  ELSE
    -- A name, code, activation, or posting-policy edit does not change which
    -- book is authoritative. Keep those existing lifecycle controls intact.
    IF new.is_primary = old.is_primary AND new.org_id = old.org_id AND new.id = old.id THEN
      RETURN new;
    END IF;
    IF old.is_primary THEN source_org := old.org_id; END IF;
    IF new.is_primary THEN target_org := new.org_id; END IF;
  END IF;
  -- A pre-existing REPEATABLE READ snapshot could miss a first journal that
  -- committed before we acquired the book lock (SHARE did not change its row).
  -- These rare configuration writes require fresh statement snapshots.
  IF current_setting('transaction_isolation') NOT IN ('read committed', 'read uncommitted') THEN
    RAISE EXCEPTION 'Primary book identity changes require READ COMMITTED isolation; retry the configuration in a new READ COMMITTED transaction'
      USING ERRCODE = '25000';
  END IF;
  -- SQL callers may already hold the target book row when this trigger runs.
  -- Never wait in the inverse target -> authority order: contention fails
  -- closed and the caller can retry the whole transaction. The setup service
  -- acquires authority first, so its ordinary wait/recheck path is unchanged.
  PERFORM id FROM public.accounting_books
    WHERE org_id IN (source_org, target_org) AND is_primary
    ORDER BY id FOR UPDATE NOWAIT;
  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE org_id IN (source_org, target_org))
     OR EXISTS (SELECT 1 FROM public.reconciliations WHERE org_id IN (source_org, target_org)) THEN
    RAISE EXCEPTION 'Cannot reassign the primary book while journal entries or bank reconciliation sessions/history exist; a controlled book conversion is required'
      USING ERRCODE = '23514';
  END IF;
  IF tg_op = 'DELETE' THEN RETURN old; END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.project_financial_adjustment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project financial adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_financial_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.measure = new.measure
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing project financial adjustment must exactly offset the same project and measure';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.project_financial_profile_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  publish_mode boolean :=
    coalesce(current_setting('openbooks.publish_project_profile', true), 'off') = 'on';
  correction_mode boolean :=
    coalesce(current_setting('openbooks.correct_project_profile', true), 'off') = 'on';
  correction_reason text :=
    coalesce(current_setting('openbooks.project_profile_correction_reason', true), '');
BEGIN
  IF tg_op = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(old.org_id) THEN
    RETURN old;
  END IF;
  IF tg_op <> 'DELETE' AND NOT EXISTS (
    SELECT 1
      FROM project_types pt
     WHERE pt.id = new.project_type_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial profile version must belong to the project type organization';
  END IF;

  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'published project financial profile versions are immutable';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF correction_mode THEN
      IF length(btrim(correction_reason)) < 8
         OR (to_jsonb(new) - 'financial_profile' - 'updated_at' - 'updated_by')
            IS DISTINCT FROM
            (to_jsonb(old) - 'financial_profile' - 'updated_at' - 'updated_by')
      THEN
        RAISE EXCEPTION
          'controlled project financial profile correction may change only policy JSON and requires a reason';
      END IF;
    ELSIF NOT publish_mode
       OR (to_jsonb(new) - 'effective_to' - 'updated_at' - 'updated_by')
          IS DISTINCT FROM
          (to_jsonb(old) - 'effective_to' - 'updated_at' - 'updated_by')
    THEN
      RAISE EXCEPTION 'published project financial profile versions are immutable';
    END IF;
  END IF;

  -- Effective-range exclusivity is owned by the
  -- project_financial_profile_versions_no_overlap exclusion constraint
  -- (0051). Publish-mode window closing and correction-mode immutability
  -- above are unchanged.
  RETURN new;
END;
$function$

