CREATE OR REPLACE FUNCTION public.protect_report_run_authorization()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.authorization_snapshot IS NOT DISTINCT FROM OLD.authorization_snapshot THEN
    RETURN NEW;
  END IF;
  -- A missing snapshot behaves like an empty object for the one allowed
  -- transition below, but it may gain nothing beyond that single key.
  IF OLD.authorization_snapshot IS NULL THEN
    IF jsonb_typeof(NEW.authorization_snapshot) = 'object'
       AND NEW.authorization_snapshot
           = jsonb_build_object('requiredPermissions', NEW.authorization_snapshot->'requiredPermissions')
       AND jsonb_typeof(NEW.authorization_snapshot->'requiredPermissions') = 'array' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  IF jsonb_typeof(OLD.authorization_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- An already-recorded requiredPermissions is evidence: it never moves.
  IF OLD.authorization_snapshot ? 'requiredPermissions' THEN
    RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
  END IF;
  -- Otherwise NEW must be OLD plus exactly the recorded key (jsonb
  -- equality: every other key identical, the new key an array).
  IF jsonb_typeof(NEW.authorization_snapshot->'requiredPermissions') = 'array'
     AND (OLD.authorization_snapshot
          || jsonb_build_object('requiredPermissions', NEW.authorization_snapshot->'requiredPermissions')
         ) = NEW.authorization_snapshot THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'report run authorization_snapshot evidence is immutable';
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_tax_provision_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION
        'finalized income-tax provision runs are append-only (run %, status %)',
        OLD.id, OLD.status;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('discarded', 'superseded') THEN
    RAISE EXCEPTION
      'finalized income-tax provision runs are immutable (run %, status %)',
      OLD.id, OLD.status;
  END IF;

  IF OLD.status = 'posted' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'posted income-tax provision runs may only transition to superseded (run %)',
      OLD.id;
  END IF;

  IF OLD.status = 'posted' AND (
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.fiscal_year IS DISTINCT FROM OLD.fiscal_year
    OR NEW.period_from IS DISTINCT FROM OLD.period_from
    OR NEW.period_to IS DISTINCT FROM OLD.period_to
    OR NEW.version IS DISTINCT FROM OLD.version
    OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id
    OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
    OR NEW.posted_by IS DISTINCT FROM OLD.posted_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION
      'posted income-tax provision evidence is immutable (run %)',
      OLD.id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_temporary_difference_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_org_id uuid;
  target_run_id uuid;
  target_status text;
BEGIN
  target_org_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(target_org_id) THEN
    RETURN OLD;
  END IF;

  target_run_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.run_id ELSE NEW.run_id END;
  SELECT status
    INTO target_status
    FROM tax_provision_runs
   WHERE id = target_run_id
     AND org_id = target_org_id;

  IF target_status IS NULL THEN
    RAISE EXCEPTION 'temporary difference must reference a tenant-owned provision run';
  END IF;
  IF target_status <> 'draft' THEN
    RAISE EXCEPTION
      'temporary differences are immutable after provision finalization (run %, status %)',
      target_run_id, target_status;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

