CREATE OR REPLACE FUNCTION public.putaway_rules_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  target_code text;
  warehouse_code text;
BEGIN
  IF public.stock_location_warehouse(NEW.org_id, NEW.target_location_id) IS DISTINCT FROM NEW.warehouse_id THEN
