CREATE OR REPLACE FUNCTION public.refresh_document_totals_from_lines(p_document_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_kind text;
    v_line_count integer;
    v_amount_sum numeric;
    v_tax_sum numeric;
    v_debit_sum numeric;
    v_want_subtotal numeric;
    v_want_total numeric;
BEGIN
    SELECT kind INTO v_kind
      FROM public.documents
     WHERE id = p_document_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*)::int,
           coalesce(sum(l.amount), 0),
           coalesce(sum(l.tax_amount), 0),
           coalesce(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
      INTO v_line_count, v_amount_sum, v_tax_sum, v_debit_sum
      FROM public.document_lines l
     WHERE l.document_id = p_document_id AND l.org_id = p_org_id;
    IF v_kind IN ('journal', 'pay_run') THEN
        v_want_total := v_debit_sum;
        v_want_subtotal := v_debit_sum - v_tax_sum;
    ELSE
        v_want_subtotal := v_amount_sum;
        v_want_total := v_amount_sum + v_tax_sum;
    END IF;
    UPDATE public.documents d
       SET subtotal = v_want_subtotal,
           tax_total = v_tax_sum,
           total = v_want_total,
           updated_at = greatest(clock_timestamp(), d.updated_at + interval '1 microsecond')
     WHERE d.id = p_document_id
       AND d.org_id = p_org_id
       AND (d.subtotal, d.tax_total, d.total) IS DISTINCT FROM
           (v_want_subtotal, v_tax_sum, v_want_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.revenue_approved_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subject uuid; changed boolean; amendment uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.org_id<>OLD.org_id OR NEW.id<>OLD.id THEN RAISE EXCEPTION 'revenue identity and organization are immutable'; END IF;
 IF TG_TABLE_NAME='revenue_contracts' THEN
  IF OLD.subsidiary_id IS NOT NULL AND NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id THEN RAISE EXCEPTION 'revenue legal entity cannot be changed'; END IF;
  subject:=OLD.id; amendment:=NEW.last_change_id;
  changed:=(NEW.total_transaction_price,NEW.currency,NEW.customer_id,NEW.starts_on,NEW.ends_on) IS DISTINCT FROM
           (OLD.total_transaction_price,OLD.currency,OLD.customer_id,OLD.starts_on,OLD.ends_on);
 ELSE
  IF NEW.contract_id<>OLD.contract_id THEN RAISE EXCEPTION 'a performance obligation cannot move contracts'; END IF;
  subject:=OLD.contract_id; amendment:=NEW.last_change_id;
  changed:=(NEW.allocated_price,NEW.standalone_selling_price,NEW.recognition_rule_id,NEW.recognition_starts_on,NEW.recognition_ends_on,NEW.deferred_account_id,NEW.recognized_account_id) IS DISTINCT FROM
           (OLD.allocated_price,OLD.standalone_selling_price,OLD.recognition_rule_id,OLD.recognition_starts_on,OLD.recognition_ends_on,OLD.deferred_account_id,OLD.recognized_account_id);
 END IF;
 IF (OLD.last_change_id IS NOT NULL AND changed) OR NEW.last_change_id IS DISTINCT FROM OLD.last_change_id THEN
  IF amendment IS NULL OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=amendment AND f.org_id=OLD.org_id AND f.domain='revenue' AND f.subject_id=subject AND f.status='approved') THEN
   RAISE EXCEPTION 'approved revenue terms require a new independently approved contract modification';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.revenue_schedule_basis_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subject uuid; parent uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.change_basis IS NOT NULL AND (TG_OP='INSERT' OR NEW.change_basis IS DISTINCT FROM OLD.change_basis) THEN
  SELECT c.id,c.parent_contract_id INTO subject,parent FROM performance_obligations o JOIN revenue_contracts c ON c.id=o.contract_id AND c.org_id=o.org_id WHERE o.id=NEW.obligation_id AND o.org_id=NEW.org_id;
  IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=(NEW.change_basis->>'changeId')::uuid AND f.org_id=NEW.org_id AND f.domain='revenue' AND f.subject_id IN(subject,parent) AND f.status='approved') THEN
   RAISE EXCEPTION 'amended recognition basis requires the approved contract modification';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.change_basis IS NOT NULL AND NEW.change_basis IS NULL THEN RAISE EXCEPTION 'an approved recognition basis cannot be erased'; END IF;
 IF NEW.change_basis IS NOT NULL AND NEW.total_amount IS DISTINCT FROM (NEW.change_basis->>'totalAmount')::numeric THEN RAISE EXCEPTION 'recognition total must match its approved basis'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rma_document_kind_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  record_org uuid;
  record_kind text;
BEGIN
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'rma' THEN
    RAISE EXCEPTION 'RMA details require a return authorization document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.source_document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind NOT IN ('customer_invoice', 'sales_fulfillment') THEN
    RAISE EXCEPTION 'RMA source must be a customer invoice or sales fulfillment in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.customer_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO record_org, record_kind
      FROM public.documents WHERE id = NEW.customer_credit_id;
    IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'customer_credit' THEN
      RAISE EXCEPTION 'RMA customer credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.rma_line_kind_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  rma_org uuid;
  document_kind text;
  line_document uuid;
  source_org uuid;
  location_org uuid;
  credit_org uuid;
  credit_kind text;
  scrap_org uuid;
BEGIN
  SELECT org_id INTO rma_org FROM public.rma_documents
   WHERE document_id = NEW.document_id AND org_id = NEW.org_id;
  SELECT d.kind, l.document_id INTO document_kind, line_document
    FROM public.document_lines l JOIN public.documents d ON d.id = l.document_id AND d.org_id = l.org_id
   WHERE l.id = NEW.line_id AND l.org_id = NEW.org_id;
  IF rma_org IS NULL OR document_kind IS DISTINCT FROM 'rma' OR line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'RMA line must belong to an RMA document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id INTO source_org FROM public.inventory_movements WHERE id = NEW.source_issue_movement_id;
  IF source_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'RMA source movement must belong to the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.disposition_location_id IS NOT NULL THEN
    SELECT org_id INTO location_org FROM public.stock_locations WHERE id = NEW.disposition_location_id;
    IF location_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA disposition location must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.vendor_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO credit_org, credit_kind FROM public.documents WHERE id = NEW.vendor_credit_id;
    IF credit_org IS DISTINCT FROM NEW.org_id OR credit_kind IS DISTINCT FROM 'vendor_credit' THEN
      RAISE EXCEPTION 'RMA vendor credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.scrap_movement_id IS NOT NULL THEN
    SELECT org_id INTO scrap_org FROM public.inventory_movements WHERE id = NEW.scrap_movement_id;
    IF scrap_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA scrap movement must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.row_extra_dims_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_subsidiary uuid;
begin
  v_subsidiary := new.subsidiary_id;
  if tg_table_name = 'document_lines' and v_subsidiary is null then
    select subsidiary_id into v_subsidiary from documents where id = new.document_id;
  end if;
  if v_subsidiary is null then
    select id into v_subsidiary from subsidiaries where org_id = new.org_id and parent_id is null;
  end if;
  perform validate_extra_dims(new.org_id, new.extra_dims, v_subsidiary);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.saas_metrics_normalization_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  actor_org uuid;
  live boolean;
  prior_digest text;
  new_digest text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'saas normalization requests are durable audit and cannot be deleted; cancel the request instead'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Actor identities are validated against the subject: the requester and
  -- the approver must belong to the requesting organization.
  IF NEW.requested_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.requested_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization requester must be a user of the requesting organization; choose a requester in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.approved_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.approved_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization approver must be a user of the requesting organization; choose an approver in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.approved_by IS NOT DISTINCT FROM NEW.requested_by THEN
      RAISE EXCEPTION 'saas normalization approver must be distinct from the requester; choose a separate approver in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'pending' THEN
      RAISE EXCEPTION 'new saas normalization requests start as pending; claim the pending request to begin work'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'saas normalization approval is recorded by updating the pending request, not at insert; insert without approver, then record approval'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_heartbeat_at IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests hold no lease; claim the pending request to take a lease token'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> 0 THEN
      RAISE EXCEPTION 'new saas normalization requests start at attempt zero; claims pending attempts'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests carry no outcome; finalize a running claim to record one'
        USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_requested',
      jsonb_build_object('event', 'saas_normalization_requested', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', 0,
        'statusBefore', NULL, 'statusAfter', NEW.status,
        'priorLeaseDigest', NULL, 'newLeaseDigest', NULL,
        'actor', NEW.requested_by, 'reason', NEW.reason),
      NEW.requested_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Request identity is immutable; a new month or idempotency key is a new request.
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.month IS DISTINCT FROM OLD.month
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by THEN
    RAISE EXCEPTION 'saas normalization request identity (organization, month, idempotency key, request hash, requester) is immutable; file a new request instead'
      USING ERRCODE = 'check_violation';
  END IF;
  -- The approver is immutable once recorded; the approval timestamp follows it.
  IF OLD.approved_by IS NOT NULL AND NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
    RAISE EXCEPTION 'saas normalization approver is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NOT NULL AND NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION 'saas normalization approval time is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.approved_by IS NULL) <> (NEW.approved_at IS NULL) THEN
    RAISE EXCEPTION 'saas normalization approval needs both approver and approval time; record them together on the pending request'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Terminal rows are immutable; further work is a new request.
  IF OLD.status IN ('succeeded', 'cancelled') THEN
    RAISE EXCEPTION 'saas normalization requests in terminal state % are immutable; file a new request for further work', OLD.status
      USING ERRCODE = 'check_violation';
  END IF;

  -- Liveness: the presented token must equal the stored live token and the
  -- stored lease must not have expired. Every later mutation and
  -- finalization funnels through this flag.
  live := OLD.lease_token IS NOT NULL
          AND NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token
          AND OLD.lease_expires_at IS NOT NULL
          AND OLD.lease_expires_at > now();
  prior_digest := CASE WHEN OLD.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(OLD.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;
  new_digest := CASE WHEN NEW.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(NEW.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;

  -- Pending rows change only by recording approval, claiming, or cancelling.
  IF OLD.status = 'pending' AND NEW.status = 'pending' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at
       OR NEW.last_heartbeat_at IS DISTINCT FROM OLD.last_heartbeat_at
       OR NEW.attempt_count <> OLD.attempt_count
       OR NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL
       OR NEW.progress IS DISTINCT FROM OLD.progress THEN
      RAISE EXCEPTION 'pending saas normalization requests change only by recording approval, claiming to running, or cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    IF OLD.approved_by IS NULL AND NEW.approved_by IS NOT NULL THEN
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_approved',
        jsonb_build_object('event', 'saas_normalization_approved', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'actor', NEW.approved_by, 'reason', NEW.reason),
        NEW.approved_by, NEW.idempotency_key::text);
    END IF;
    RETURN NEW;
  END IF;

  -- First claim: pending to running opens attempt one with a fresh live lease.
  -- Execution requires a recorded approval and a presented transition actor.
  IF OLD.status = 'pending' AND NEW.status = 'running' THEN
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires a recorded approval; record approver and approval time on the pending request, then claim'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM NEW.approved_by THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires the approver as the acting user; record the approver as updated_by when claiming'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'claiming a saas normalization request needs a fresh lease token with a future expiry; generate a token and claim again'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'claiming a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a claimed saas normalization request carries no outcome yet; finalize after work completes'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_claimed',
      jsonb_build_object('event', 'saas_normalization_claimed', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'pending' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.requested_by THEN
      RAISE EXCEPTION 'cancelling a pending saas normalization request requires the requester as the acting user; record the requester as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'cancelling an unclaimed saas normalization request takes no lease; cancel without lease fields'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Running to running: either a live heartbeat under the live token, or a
  -- stale reacquisition after expiry. Heartbeats manufacture no audit event.
  IF OLD.status = 'running' AND NEW.status = 'running' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token THEN
      IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at > now() THEN
        RAISE EXCEPTION 'saas normalization lease is still live; heartbeat with the live token, or wait for expiry and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request requires the approver as the acting user; record the approver as updated_by when reacquiring'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request needs a fresh lease token with a future expiry; generate a token and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a reacquired saas normalization request carries no outcome yet; finalize after work completes'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.last_heartbeat_at := now();
      NEW.updated_at := now();
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_abandoned',
        jsonb_build_object('event', 'saas_normalization_abandoned', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', OLD.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text),
        (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_reacquired',
        jsonb_build_object('event', 'saas_normalization_reacquired', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text);
      RETURN NEW;
    END IF;
    IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'saas normalization lease has expired; reacquire with a fresh token before further heartbeats'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'saas normalization heartbeat requires the approver as the acting user; record the approver as updated_by when heartbeating'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'heartbeats open no new attempts; keep attempt_count at % or reacquire after expiry', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_expires_at < OLD.lease_expires_at THEN
      RAISE EXCEPTION 'heartbeats may extend the saas normalization lease expiry, never shorten it'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'running saas normalization requests carry progress only; finalize to record an outcome'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- Finalization under the live lease token: exactly one terminal event.
  IF OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed') THEN
    IF NOT live THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the live lease token; heartbeat or reacquire first, then finalize'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the approver as the acting user; record the approver as updated_by when finalizing'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'finalization closes the current attempt; keep attempt_count at %', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'succeeded' THEN
      IF NEW.result IS NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization must store its result; include the result document'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization carries a result, not a failure; clear failure and remedy'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.failure IS NULL OR btrim(NEW.failure) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the failure; describe what went wrong'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.remedy IS NULL OR btrim(NEW.remedy) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the remedy; record how the operator recovers'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL THEN
        RAISE EXCEPTION 'a failed saas normalization carries failure and remedy, not a result; clear the result'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id,
      CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
      jsonb_build_object('event', CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
        'requestId', NEW.id, 'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'running' AND NEW.status = 'cancelled' THEN
    IF NOT live THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the live lease token; heartbeat or reacquire first'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Retry from failure re-enters the lifecycle with a fresh live lease.
  IF OLD.status = 'failed' AND NEW.status = 'running' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when retrying'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request needs a fresh lease token with a future expiry; generate a token and retry'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a retried saas normalization request starts clear; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_retried',
      jsonb_build_object('event', 'saas_normalization_retried', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'failed' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'saas normalization requests move pending to running to succeeded, failed or cancelled, and failed may retry to running; % to % is not a legal transition', OLD.status, NEW.status
    USING ERRCODE = 'check_violation';
END
$function$

CREATE OR REPLACE FUNCTION public.sales_capture_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE is_credit boolean:=false; is_reversal boolean:=false; old_won boolean:=false; new_won boolean:=false; prior public.crm_sales_evidence; metric_name text; source_name text; source_number_value text; value numeric; event_date date;
BEGIN
 IF TG_TABLE_NAME='documents' THEN
  IF NEW.kind NOT IN ('customer_invoice','customer_credit') THEN RETURN NEW; END IF;
  metric_name:='net_invoiced'; source_name:='document'; source_number_value:=NEW.document_number;
  is_credit:=NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted');
  is_reversal:=TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status='voided';
  value:=CASE WHEN NEW.kind='customer_credit' THEN -NEW.subtotal ELSE NEW.subtotal END;
  event_date:=COALESCE(NEW.posting_date,NEW.document_date);
  IF is_reversal THEN
   -- Finalized voids clear request fields. The posted reversal is the
   -- authoritative effective date for both accounting and sales evidence.
   SELECT reversal.posting_date INTO event_date
     FROM public.journal_entries reversal
    WHERE reversal.org_id=NEW.org_id
      AND reversal.id=NEW.reversal_entry_id
      AND reversal.reverses_entry_id=NEW.posted_entry_id
      AND reversal.status='posted';
  END IF;
 ELSE
  metric_name:='closed_won'; source_name:='opportunity'; source_number_value:=NEW.opportunity_number;
  SELECT is_won INTO new_won FROM public.crm_opportunity_statuses WHERE org_id=NEW.org_id AND id=NEW.status_id;
  IF TG_OP='UPDATE' THEN SELECT is_won INTO old_won FROM public.crm_opportunity_statuses WHERE org_id=OLD.org_id AND id=OLD.status_id; END IF;
  is_credit:=COALESCE(new_won,false) AND NOT COALESCE(old_won,false);
  is_reversal:=COALESCE(old_won,false) AND NOT COALESCE(new_won,false);
  IF TG_OP='UPDATE' AND old_won AND new_won AND
    (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id OR OLD.projected_amount IS DISTINCT FROM NEW.projected_amount OR OLD.currency IS DISTINCT FROM NEW.currency) THEN
   RAISE EXCEPTION 'Closed-won sales evidence is immutable; reopen the opportunity with a reason before adjusting it.' USING ERRCODE='23514';
  END IF;
  value:=NEW.projected_amount; event_date:=(NEW.closed_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date;
  IF is_reversal AND NULLIF(trim(NEW.win_loss_reason),'') IS NULL THEN RAISE EXCEPTION 'Enter the reason for reopening this opportunity.' USING ERRCODE='23514'; END IF;
 END IF;
 IF is_credit THEN
  IF event_date IS NULL THEN RAISE EXCEPTION 'Sales evidence requires an effective date.' USING ERRCODE='23514'; END IF;
  INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,created_by)
   VALUES(NEW.org_id,source_name,NEW.id,source_number_value,NEW.revision_seq,'credit',metric_name,NEW.sales_rep_id,NEW.sales_team_id,NEW.subsidiary_id,NEW.currency,value,event_date,NEW.updated_by);
 ELSIF is_reversal THEN
  SELECT e.* INTO prior FROM public.crm_sales_evidence e WHERE e.org_id=NEW.org_id AND e.source_kind=source_name AND e.source_id=NEW.id AND e.event_kind='credit' AND NOT EXISTS (SELECT 1 FROM public.crm_sales_evidence r WHERE r.org_id=e.org_id AND r.reverses_id=e.id) ORDER BY e.created_at DESC LIMIT 1;
  IF FOUND THEN
   IF source_name='opportunity' THEN event_date:=(NEW.updated_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date; END IF;
   IF event_date IS NULL THEN RAISE EXCEPTION 'A sales reversal requires its controlled effective date.' USING ERRCODE='23514'; END IF;
   INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,reverses_id,created_by)
    VALUES(prior.org_id,prior.source_kind,prior.source_id,prior.source_number,NEW.revision_seq,'reversal',prior.metric,prior.employee_id,prior.sales_team_id,prior.subsidiary_id,prior.currency,-prior.amount,event_date,prior.id,NEW.updated_by);
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_customer_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE account public.crm_account_profiles;
BEGIN
 IF TG_OP='UPDATE' AND OLD.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 SELECT * INTO account FROM public.crm_account_profiles WHERE org_id=NEW.org_id AND party_id=NEW.party_id FOR UPDATE;
 IF NOT FOUND OR account.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 UPDATE public.crm_account_profiles SET sales_rep_id=NEW.sales_rep_id,updated_at=clock_timestamp(),updated_by=NEW.updated_by WHERE org_id=NEW.org_id AND id=account.id;
 INSERT INTO public.crm_account_assignment_events(org_id,account_profile_id,from_employee_id,to_employee_id,from_owner_user_id,to_owner_user_id,from_territory_id,to_territory_id,source,reason,created_by,updated_by)
 VALUES(NEW.org_id,account.id,account.sales_rep_id,NEW.sales_rep_id,account.owner_user_id,account.owner_user_id,account.territory_id,account.territory_id,'manual','Customer sales representative changed',NEW.updated_by,NEW.updated_by);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_document_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status IN ('posted','voided') AND (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id) THEN
  RAISE EXCEPTION 'Posted sales attribution is immutable.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted') AND NEW.kind IN ('customer_invoice','customer_credit') AND NEW.sales_rep_id IS NULL THEN
  SELECT c.sales_rep_id INTO NEW.sales_rep_id FROM public.customer_roles c WHERE c.org_id=NEW.org_id AND c.party_id=NEW.party_id;
  IF NEW.sales_team_id IS NULL THEN
   SELECT (v.definition->>'sales_team_id')::uuid INTO NEW.sales_team_id FROM public.crm_account_profiles cp
    JOIN LATERAL(SELECT definition FROM public.crm_sales_territory_versions v WHERE v.org_id=cp.org_id AND v.territory_id=cp.territory_id AND v.effective_from<=COALESCE(NEW.posting_date,NEW.document_date) ORDER BY effective_from DESC,revision DESC LIMIT 1)v ON true
    WHERE cp.org_id=NEW.org_id AND cp.party_id=NEW.party_id AND cp.sales_rep_id=NEW.sales_rep_id;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_employee_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE field_name text; employee uuid; before_value jsonb; after_value jsonb;
BEGIN
 after_value:=to_jsonb(NEW);
 IF TG_OP='UPDATE' THEN before_value:=to_jsonb(OLD); ELSE before_value:='{}'::jsonb; END IF;
 FOREACH field_name IN ARRAY TG_ARGV LOOP
  employee:=NULLIF(after_value->>field_name,'')::uuid;
  IF employee IS NOT NULL AND (TG_OP='INSERT' OR before_value->field_name IS DISTINCT FROM after_value->field_name) THEN
   PERFORM 1 FROM public.employee_roles e JOIN public.parties p ON p.org_id=e.org_id AND p.id=e.party_id
    WHERE e.org_id=NEW.org_id AND e.party_id=employee AND e.is_active AND e.is_sales_rep AND p.is_active
    AND (e.sales_rep_since IS NULL OR e.sales_rep_since<=COALESCE((after_value->>'period_start')::date,(after_value->>'valid_from')::date,(after_value->>'effective_from')::date,CURRENT_DATE)) FOR SHARE OF e,p;
   IF NOT FOUND THEN RAISE EXCEPTION 'Select an active employee designated as a sales representative in Sales → Representatives.' USING ERRCODE='23514'; END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_legacy_identity_guard()
