CREATE OR REPLACE FUNCTION public.sales_quota_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND public.app_bypass_rls_active() AND current_setting('openbooks.amend',true)='on' THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Quota history cannot be deleted; close the quota instead.' USING ERRCODE='23514'; END IF;
 IF OLD.lifecycle IN ('approved','superseded','closed') AND
  (to_jsonb(NEW)-ARRAY['lifecycle','updated_at','updated_by','revision']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['lifecycle','updated_at','updated_by','revision']) THEN
  RAISE EXCEPTION 'Approved quotas are immutable; create a revised quota with a reason and approval.' USING ERRCODE='23514';
 END IF;
 IF NEW.lifecycle IS DISTINCT FROM OLD.lifecycle AND NOT (
  (OLD.lifecycle='draft' AND NEW.lifecycle='pending_approval') OR
  (OLD.lifecycle='pending_approval' AND NEW.lifecycle IN ('draft','approved')) OR
  (OLD.lifecycle='approved' AND NEW.lifecycle IN ('superseded','closed'))) THEN
  RAISE EXCEPTION 'Invalid quota lifecycle transition.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.scheduler_outbox_terminal_audit_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'scheduler_outbox_terminal_audit is append-only';
END $function$

CREATE OR REPLACE FUNCTION public.scheduler_outbox_terminal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_frozen boolean;
BEGIN
  IF OLD.terminal_failed_at IS NULL THEN
    RETURN NEW;
  END IF;
  v_frozen :=
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.kind IS DISTINCT FROM OLD.kind
    OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
    OR NEW.occurrence_key IS DISTINCT FROM OLD.occurrence_key
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.terminal_failed_at IS DISTINCT FROM OLD.terminal_failed_at
    OR NEW.terminal_failed_by IS DISTINCT FROM OLD.terminal_failed_by;
  IF NOT v_frozen THEN
    RETURN NEW;
  END IF;
  IF NEW.terminal_failed_at IS NOT DISTINCT FROM OLD.terminal_failed_at
     AND NEW.terminal_failed_by IS NOT DISTINCT FROM OLD.terminal_failed_by THEN
    -- Only non-stamp frozen facts moved; nothing authorizes those either.
    RAISE EXCEPTION 'scheduler_outbox terminal-failure evidence is immutable; authorize a replay to reset it';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.scheduler_outbox_terminal_audit prior
     WHERE prior.outbox_row_id = OLD.id
       AND prior.event = 'replay_authorized'
  ) THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its replay_authorized audit evidence first';
  END IF;
  IF public.openbooks_scheduler_outbox_replay_allowed(OLD.org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its organization''s authorization pin';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.segment_definition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and old.source_kind = 'builtin'
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'built-in segment definitions cannot be deleted' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and old.source_kind = 'builtin' and
     (new.key <> old.key or new.source_kind <> old.source_kind or new.storage_column is distinct from old.storage_column) then
    raise exception 'built-in segment identity cannot be changed' using errcode = '23514';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.segment_definitions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_value_segment uuid;
  v_line_count bigint;
begin
  if new.default_value_id is not null then
    select segment_id into v_value_segment
      from public.segment_values
     where org_id = new.org_id and id = new.default_value_id;
    if not found or v_value_segment is distinct from new.id then
      raise exception 'default value % does not belong to segment %', new.default_value_id, new.key
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.is_balancing and not new.is_balancing then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id
       and l.extra_dims ? old.key
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'segment % cannot stop balancing while % posted journal lines carry it',
        old.key, v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.segment_value_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_hierarchical boolean;
  old_scope text;
  new_scope text;
  first_scope text;
  second_scope text;
  tree_scope text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id) THEN
    old_scope := OLD.org_id::text || ':' || OLD.segment_id::text;
    new_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    first_scope := LEAST(old_scope, new_scope);
    second_scope := GREATEST(old_scope, new_scope);
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || first_scope, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || second_scope, 0)
    );
  ELSE
    tree_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || tree_scope, 0)
    );
  END IF;

  SELECT is_hierarchical INTO v_hierarchical
    FROM public.segment_definitions
   WHERE id = NEW.segment_id
     AND org_id = NEW.org_id
     AND source_kind = 'custom'
   FOR KEY SHARE;
  IF v_hierarchical IS NULL THEN
    RAISE EXCEPTION 'segment value must belong to a custom segment in this organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id)
     AND EXISTS (
       SELECT 1 FROM public.segment_values child
        WHERE child.parent_id = OLD.id
          AND child.org_id = OLD.org_id
          AND child.segment_id = OLD.segment_id
     ) THEN
    RAISE EXCEPTION 'a segment value with children cannot change organization or segment'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.subsidiary_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.subsidiaries subsidiary
     WHERE subsidiary.id = NEW.subsidiary_id AND subsidiary.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'segment value subsidiary belongs to another organization'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.parent_id IS NOT NULL THEN
    IF NOT v_hierarchical THEN
      RAISE EXCEPTION 'this segment is not hierarchical' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.segment_values parent
       WHERE parent.id = NEW.parent_id
         AND parent.org_id = NEW.org_id
         AND parent.segment_id = NEW.segment_id
    ) THEN
      RAISE EXCEPTION 'segment value parent is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id = NEW.id OR EXISTS (
      WITH RECURSIVE descendants AS (
        SELECT id
          FROM public.segment_values
         WHERE org_id = NEW.org_id
           AND segment_id = NEW.segment_id
           AND parent_id = NEW.id
        UNION
        SELECT value.id
          FROM public.segment_values value
          JOIN descendants descendant ON value.parent_id = descendant.id
         WHERE value.org_id = NEW.org_id
           AND value.segment_id = NEW.segment_id
      )
      SELECT 1 FROM descendants WHERE id = NEW.parent_id
    ) THEN
      RAISE EXCEPTION 'segment value hierarchy contains a cycle' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.stock_location_warehouse(p_org_id uuid, p_stock_location_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  current_id uuid := p_stock_location_id;
  current_kind text;
  next_id uuid;
  depth integer := 0;
BEGIN
  WHILE current_id IS NOT NULL LOOP
    SELECT sl.kind, sl.parent_id INTO current_kind, next_id
      FROM public.stock_locations sl
     WHERE sl.id = current_id AND sl.org_id = p_org_id;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    IF current_kind = 'warehouse' THEN
      RETURN current_id;
    END IF;
    depth := depth + 1;
    IF depth > 64 THEN
      RAISE EXCEPTION 'stock location % has a parent chain deeper than 64 levels or a cycle', p_stock_location_id;
    END IF;
    current_id := next_id;
  END LOOP;
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.stock_locations_warehouse_nesting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  enclosing uuid;
  enclosing_code text;
  nested_code text;
BEGIN
  enclosing := public.stock_location_warehouse(NEW.org_id, NEW.parent_id);
  IF NEW.kind = 'warehouse' AND enclosing IS NOT NULL THEN
    SELECT code INTO enclosing_code FROM public.stock_locations WHERE id = enclosing AND org_id = NEW.org_id;
    RAISE EXCEPTION 'warehouse % cannot sit inside warehouse %; make it a zone or move it out', NEW.code, enclosing_code
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.kind = 'warehouse' OR enclosing IS NOT NULL) THEN
    WITH RECURSIVE below AS (
      SELECT c.id, c.code, c.kind, 1 AS depth
        FROM public.stock_locations c
       WHERE c.parent_id = NEW.id AND c.org_id = NEW.org_id
      UNION ALL
      SELECT c.id, c.code, c.kind, b.depth + 1
        FROM below b
        JOIN public.stock_locations c ON c.parent_id = b.id AND c.org_id = NEW.org_id
       WHERE b.depth < 64
    )
    SELECT code INTO nested_code FROM below WHERE kind = 'warehouse' LIMIT 1;
    IF nested_code IS NOT NULL THEN
      RAISE EXCEPTION 'warehouse % cannot sit inside another warehouse; make it a zone or move it out', nested_code
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.subscription_amendment_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF OLD.status = 'applied' THEN
    RAISE EXCEPTION 'applied subscription amendments are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.subscription_period_invoice_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'subscription period invoice lineage is immutable';
END $function$

CREATE OR REPLACE FUNCTION public.subscription_plan_version_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF OLD.status IN ('published','superseded') THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'published subscription plan versions are immutable';
    END IF;
    IF ROW(OLD.plan_id,OLD.effective_from,OLD.name,OLD.description,OLD.currency_code,OLD.interval,OLD.interval_count,OLD.billing_timing,OLD.published_at,OLD.published_by)
      IS DISTINCT FROM ROW(NEW.plan_id,NEW.effective_from,NEW.name,NEW.description,NEW.currency_code,NEW.interval,NEW.interval_count,NEW.billing_timing,NEW.published_at,NEW.published_by)
    THEN
      RAISE EXCEPTION 'published subscription plan commercial terms are immutable';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.subscription_version_component_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_version uuid; parent_status text;
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  parent_version := CASE WHEN TG_OP = 'DELETE' THEN OLD.version_id ELSE NEW.version_id END;
  SELECT status INTO parent_status FROM subscription_plan_versions WHERE id=parent_version;
  IF parent_status IN ('published','superseded') THEN
    RAISE EXCEPTION 'components of published subscription plan versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.subsidiary_ref_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.subsidiary_id is not null and not exists (
    select 1 from subsidiaries s where s.id = new.subsidiary_id and s.org_id = new.org_id
  ) then
    raise exception 'subsidiary belongs to another organization' using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.subsidiary_tree_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  first_org uuid;
  second_org uuid;
  tree_org uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.org_id IS DISTINCT FROM NEW.org_id THEN
    first_org := LEAST(OLD.org_id::text, NEW.org_id::text)::uuid;
    second_org := GREATEST(OLD.org_id::text, NEW.org_id::text)::uuid;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || first_org::text, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || second_org::text, 0)
    );
  ELSE
    tree_org := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('subsidiary-tree:' || tree_org::text, 0)
    );
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.parent_id IS NULL
       AND EXISTS (SELECT 1 FROM public.orgs WHERE id = OLD.org_id)
       AND NOT public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RAISE EXCEPTION 'the root subsidiary cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.parent_id IS NULL AND NEW.parent_id IS NOT NULL THEN
    RAISE EXCEPTION 'the root subsidiary cannot be moved' USING ERRCODE = '23514';
  END IF;
  IF NEW.parent_id IS NULL AND NOT NEW.is_active THEN
    RAISE EXCEPTION 'the root subsidiary cannot be inactive' USING ERRCODE = '23514';
  END IF;
  IF NEW.parent_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
        FROM public.subsidiaries parent
       WHERE parent.id = NEW.parent_id
         AND parent.org_id = NEW.org_id
    ) THEN
      RAISE EXCEPTION 'subsidiary parent belongs to another organization' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id = NEW.id OR EXISTS (
      WITH RECURSIVE descendants AS (
        SELECT id
          FROM public.subsidiaries
         WHERE org_id = NEW.org_id AND parent_id = NEW.id
        UNION ALL
        SELECT subsidiary.id
          FROM public.subsidiaries subsidiary
          JOIN descendants descendant ON subsidiary.parent_id = descendant.id
         WHERE subsidiary.org_id = NEW.org_id
      )
      SELECT 1 FROM descendants WHERE id = NEW.parent_id
    ) THEN
      RAISE EXCEPTION 'subsidiary hierarchy contains a cycle' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tax_filing_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    raise exception 'tax filing snapshots cannot be deleted';
  end if;
  if old.status = 'prepared' and new.status = 'filed'
     and (to_jsonb(new) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
       = (to_jsonb(old) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
  then
    return new;
  end if;
  raise exception 'tax filing snapshots are immutable';
end $function$

CREATE OR REPLACE FUNCTION public.tax_group_member_validate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare group_org uuid; code_org uuid;
begin
  if new.sequence <= 0 then raise exception 'tax group member sequence must be positive'; end if;
  select org_id into group_org from tax_groups where id = new.tax_group_id;
  select org_id into code_org from tax_codes where id = new.tax_code_id;
  if group_org is null or code_org is null or group_org <> code_org then
    raise exception 'tax group and tax code must belong to the same organization';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.time_entries_default_work_region()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_site text;
  v_profile_region text;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.work_region IS NULL THEN
    IF NEW.project_id IS NOT NULL THEN
      SELECT p.site_jurisdiction INTO v_site
        FROM public.projects p
       WHERE p.org_id = NEW.org_id AND p.id = NEW.project_id;
    END IF;
    IF v_site IS NOT NULL THEN
      NEW.work_region := CASE WHEN v_site LIKE '%-%'
        THEN split_part(v_site, '-', 2) ELSE v_site END;
      NEW.work_region_source := 'project_site';
    ELSE
      SELECT ep.province INTO v_profile_region
        FROM public.employee_payroll_profiles ep
       WHERE ep.org_id = NEW.org_id AND ep.employee_party_id = NEW.employee_party_id
       ORDER BY ep.updated_at DESC, ep.id
       LIMIT 1;
      IF v_profile_region IS NOT NULL THEN
        NEW.work_region := v_profile_region;
        NEW.work_region_source := 'payroll_profile';
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND
     (NEW.work_region, NEW.work_subregion) IS DISTINCT FROM
     (OLD.work_region, OLD.work_subregion) THEN
    IF EXISTS (
      SELECT 1 FROM public.pay_stubs s
      JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
      JOIN public.documents d ON d.org_id = r.org_id AND d.id = r.document_id
      WHERE s.org_id = NEW.org_id AND s.employee_party_id = NEW.employee_party_id
        AND NEW.worked_on BETWEEN r.period_start AND r.period_end
        AND r.run_status = 'committed' AND d.status <> 'voided'
    ) THEN
      RAISE EXCEPTION 'Payroll work jurisdiction is locked because a payroll run covering this service date is committed'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.work_region_source IS DISTINCT FROM 'hr_override'
       OR nullif(btrim(NEW.work_region_reason), '') IS NULL THEN
      RAISE EXCEPTION 'Changing a time entry work jurisdiction requires an HR override reason'
        USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (NEW.org_id, 'time_entries', NEW.id, 'work_jurisdiction_override',
      jsonb_build_object('before', jsonb_build_object('region', OLD.work_region, 'subregion', OLD.work_subregion),
                         'after', jsonb_build_object('region', NEW.work_region, 'subregion', NEW.work_subregion),
                         'reason', NEW.work_region_reason), NEW.updated_by);
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_application_open_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_doc uuid;
begin
  if openbooks_sandbox_wipe_allowed(
       case when tg_op = 'DELETE' then old.org_id else new.org_id end
     ) then
    return null;
  end if;
  for v_doc in
    select distinct d.id
      from documents d
      join journal_lines jl on jl.entry_id = d.posted_entry_id
     where jl.is_open_item
       and jl.id in (coalesce(new.to_line_id, old.to_line_id),
                     coalesce(new.from_line_id, old.from_line_id))
  loop
    perform recompute_document_open_balance(v_doc);
  end loop;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.trg_hrm_survey_response_unique_questions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT public.hrm_survey_answers_have_unique_question_ids(NEW.answers) THEN
    RAISE EXCEPTION 'survey response must contain at most one answer per question'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'hrm_survey_responses_unique_question_ids';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_journal_line_open_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_entries uuid[];
  v_entry uuid;
  v_doc uuid;
  v_org uuid;
begin
  if tg_op = 'DELETE' then
    v_entries := array[old.entry_id];
    v_org := old.org_id;
  elsif tg_op = 'INSERT' then
    v_entries := array[new.entry_id];
    v_org := new.org_id;
  elsif new.entry_id is distinct from old.entry_id
     or new.account_id is distinct from old.account_id
     or new.amount is distinct from old.amount
     or new.txn_amount is distinct from old.txn_amount
     or new.currency is distinct from old.currency
     or new.is_open_item is distinct from old.is_open_item then
    v_entries := array[old.entry_id, new.entry_id];
    v_org := new.org_id;
  else
    return new;
  end if;
  for v_entry in select distinct e from unnest(v_entries) as e loop
    for v_doc in select d.id from public.documents d
                  where d.org_id = v_org and d.posted_entry_id = v_entry loop
      perform public.recompute_document_open_balance(v_doc);
    end loop;
  end loop;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.usage_prepaid_draws_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'prepaid draw evidence is append-only';
END;
$function$

CREATE OR REPLACE FUNCTION public.usage_rating_bands_draft_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_org uuid;
  target_version uuid;
  version_status text;
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    target_org := OLD.org_id;
    target_version := OLD.plan_version_id;
    SELECT status INTO version_status FROM public.usage_rating_plan_versions
      WHERE org_id = target_org AND id = target_version;
    IF version_status = 'published' THEN
      RAISE EXCEPTION 'bands of a published usage rating plan version are immutable; publish a new version';
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT status INTO version_status FROM public.usage_rating_plan_versions
      WHERE org_id = NEW.org_id AND id = NEW.plan_version_id;
    IF version_status = 'published' THEN
      RAISE EXCEPTION 'bands of a published usage rating plan version are immutable; publish a new version';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.usage_rating_published_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'usage rating plan versions must be created as drafts';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'published' THEN
    RAISE EXCEPTION 'published usage rating plan versions are immutable; publish a new version';
  END IF;
  IF TG_OP = 'DELETE' AND OLD.status = 'published' THEN
    RAISE EXCEPTION 'published usage rating plan versions are immutable; retain the published version';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_application_idempotency_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users
     WHERE id = NEW.actor_id AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'application operation actor must belong to the organization';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_country_tax_pack_installation_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.installed_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.installed_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack installer must belong to the installation organization';
  END IF;
  IF NEW.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.superseded_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack superseding actor must belong to the installation organization';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_document_posted_period_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  current_status text;
  current_entry_id uuid;
  current_period_id uuid;
  current_org_id uuid;
  entry_period_id uuid;
  entry_org_id uuid;
BEGIN
  SELECT status, posted_entry_id, posting_period_id, org_id
    INTO current_status, current_entry_id, current_period_id, current_org_id
    FROM documents
   WHERE id = NEW.id;

  -- The document may have been deleted later in the same transaction.
  IF NOT FOUND OR current_status <> 'posted' THEN
    RETURN NULL;
  END IF;
  IF current_entry_id IS NULL OR current_period_id IS NULL THEN
    RAISE EXCEPTION 'posted document requires exact journal and accounting-period identity';
  END IF;
  SELECT period_id, org_id
    INTO entry_period_id, entry_org_id
    FROM journal_entries
   WHERE id = current_entry_id;
  IF entry_period_id IS NULL
     OR entry_org_id <> current_org_id
     OR entry_period_id <> current_period_id THEN
    RAISE EXCEPTION 'document posting period must equal its posted journal period';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_extra_dims(p_org_id uuid, p_dims jsonb, p_subsidiary_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
AS $function$
declare d record;
begin
  if jsonb_typeof(coalesce(p_dims, '{}'::jsonb)) <> 'object' then
    raise exception 'custom segment assignments must be an object' using errcode = '23514';
  end if;
  for d in
    select pair.key, pair.value, sv.subsidiary_id, sv.subsidiary_include_children
      from jsonb_each_text(coalesce(p_dims, '{}'::jsonb)) pair
      left join segment_definitions sd on sd.org_id = p_org_id and sd.key = pair.key
       and sd.source_kind = 'custom' and sd.is_active
      left join segment_values sv on sv.segment_id = sd.id and sv.org_id = sd.org_id
       and sv.id::text = pair.value and sv.is_active
  loop
    if d.subsidiary_include_children is null then
      raise exception 'invalid custom segment assignment for %', d.key using errcode = '23514';
    end if;
    if d.subsidiary_id is not null and p_subsidiary_id is not null and not (
      p_subsidiary_id = d.subsidiary_id or (
        d.subsidiary_include_children and exists (
          with recursive descendants as (
            select id from subsidiaries where id = d.subsidiary_id and org_id = p_org_id
            union all
            select s.id from subsidiaries s join descendants x on s.parent_id = x.id
             where s.org_id = p_org_id
          ) select 1 from descendants where id = p_subsidiary_id
        )
      )
    ) then
      raise exception 'custom segment value % is restricted to another subsidiary', d.value using errcode = '23514';
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.warehouses_location_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  location_kind text;
  location_code text;
BEGIN
  SELECT kind, code INTO location_kind, location_code
    FROM public.stock_locations
   WHERE id = NEW.stock_location_id AND org_id = NEW.org_id;
  IF location_kind IS DISTINCT FROM 'warehouse' THEN
    RAISE EXCEPTION 'stock location % is a %, not a warehouse; only a warehouse-kind location can be a warehouse',
      coalesce(location_code, NEW.stock_location_id::text), coalesce(location_kind, 'missing location')
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.wip_prebill_event_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'WIP prebill events are append-only';
END $function$

CREATE OR REPLACE FUNCTION public.wip_prebill_source_reservation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_status text; source_key uuid;
BEGIN
  SELECT status INTO parent_status FROM wip_prebills WHERE org_id=NEW.org_id AND id=NEW.prebill_id;
  IF parent_status NOT IN ('draft','review','approved') THEN RETURN NEW; END IF;
  source_key := coalesce(NEW.time_entry_id, NEW.document_line_id);
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text||':'||NEW.source_type||':'||source_key::text,0));
  IF EXISTS (SELECT 1 FROM wip_prebill_lines line JOIN wip_prebills worksheet ON worksheet.org_id=line.org_id AND worksheet.id=line.prebill_id
    WHERE line.org_id=NEW.org_id AND line.id<>NEW.id AND line.source_type=NEW.source_type
      AND coalesce(line.time_entry_id,line.document_line_id)=source_key AND worksheet.status IN ('draft','review','approved'))
  THEN RAISE EXCEPTION 'WIP source is already reserved by an active prebill'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.worker_employments_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE survivor uuid;
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'worker_employments: org_id is immutable (composite children reference it)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.employer_subsidiary_id IS DISTINCT FROM OLD.employer_subsidiary_id THEN
    RAISE EXCEPTION 'worker_employments: employer_subsidiary_id is immutable (transfer = terminate + rehire, never an edit)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.worker_party_id IS DISTINCT FROM OLD.worker_party_id THEN
    -- The marker is the WHOLE contract (merge-owner guarantee): the
    -- absorbed party carries custom.merged_into.survivor, written inside
    -- the merge transaction with the absorbed row deactivated, never
    -- deleted. Deliberately NOT the audit_log row: audit shape is the merge
    -- module's internal detail, and gating a data constraint on a
    -- compliance artifact would couple this table to that shape forever.
    SELECT (custom->'merged_into'->>'survivor')::uuid INTO survivor
      FROM public.parties WHERE id = OLD.worker_party_id AND org_id = OLD.org_id;
    IF survivor IS DISTINCT FROM NEW.worker_party_id THEN
      RAISE EXCEPTION 'worker_employments: worker_party_id changes only through the audited native party merge (engine/src/sync/party-merges.ts)'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END $function$
